  <script>
    (() => {
      const VALID_THEMES = new Set(['warm-white', 'paper-white', 'dark', 'green']);
      const savedTheme = localStorage.getItem('kivotos-theme') || localStorage.getItem('theme') || 'warm-white';
      const initialTheme = VALID_THEMES.has(savedTheme) ? savedTheme : 'warm-white';
      window.__initialTheme = initialTheme;
      document.documentElement.style.colorScheme = initialTheme === 'dark' ? 'dark' : 'light';
      /* Android WebView applies a different disabled-control palette and backdrop
         compositing path. Mark only the TT mobile host so the event card can use
         stable, explicit colors without changing the rest of the reader theme. */
      const syncTtMobileHost = () => {
        try {
          const host = window.parent && window.parent !== window ? window.parent : window;
          const topHost = window.top || host;
          const rootStyle = getComputedStyle(document.documentElement);
          const hasViewportContract = !!String(rootStyle.getPropertyValue('--tt-base-viewport-height') || '').trim();
          const hasTauriTavern = hasViewportContract
            || !!(host.__TAURITAVERN__ || topHost.__TAURITAVERN__ || window.__TAURITAVERN__);
          const nav = topHost.navigator || navigator;
          const mobile = /android|iphone|ipad|ipod/i.test(String(nav.userAgent || ''))
            || (Number(nav.maxTouchPoints || 0) > 0 && !!topHost.matchMedia?.('(pointer: coarse)')?.matches);
          document.documentElement.toggleAttribute('data-tt-mobile', hasTauriTavern && mobile);
          if (hasTauriTavern && mobile) document.documentElement.dataset.ttMobile = '1';
        } catch (e) {}
      };
      window.__syncTtMobileHost = syncTtMobileHost;
      syncTtMobileHost();
      addEventListener('DOMContentLoaded', syncTtMobileHost, { once: true });
      setTimeout(syncTtMobileHost, 240);
    })();
  </script>
