  <script>
    document.body.setAttribute('data-theme', window.__initialTheme || 'warm-white');

    (() => {
      const initialFontFamilies = {
        'theme-default': '',
        'zhenkai': '"LXGW ZhenKai GB", "LXGW ZhenKai", "Source Han Serif SC", "Songti SC", "STSong", "SimSun", serif',
        'noto-serif': '"Source Han Serif SC", "Source Han Serif CN", "Noto Serif CJK SC", "Noto Serif SC", "Songti SC", "STSong", serif',
        'yahei': '"Microsoft YaHei UI", "Microsoft YaHei", "PingFang SC", "Noto Sans SC", sans-serif',
        'heiti': '"SimHei", "Heiti SC", "Microsoft YaHei UI", sans-serif',
        'songti': '"SimSun", "Songti SC", "STSong", "Noto Serif SC", serif',
        'kaiti': '"KaiTi", "Kaiti SC", "STKaiti", "DFKai-SB", serif',
        'fangsong': '"FangSong", "FangSong_GB2312", "STFangsong", serif'
      };
      // 未显式选择过字体时走 'theme-default'（不写内联变量），由各主题自己决定默认字体：
      // 白昼/纯白/茶色 = 霞鹜臻楷，黑夜 = 系统无衬线
      const savedFontKey = localStorage.getItem('reading-font-family-v3') || 'theme-default';
      const initialFontKey = Object.prototype.hasOwnProperty.call(initialFontFamilies, savedFontKey)
        ? savedFontKey
        : 'theme-default';
      const initialFamily = initialFontFamilies[initialFontKey];
      if (initialFamily) {
        document.body.style.setProperty('--font-main', initialFamily);
        document.body.style.setProperty('--serif', initialFamily);
        document.body.style.setProperty('--kai', initialFamily);
      }
      window.__initialReadingFontKey = initialFontKey;
    })();
  </script>

