    function findImageListEntry(category, character, sceneType) {
      const categoryData = IMAGE_LISTS[category];
      if (!categoryData) return null;
      const nc = String(character || '').trim().normalize('NFC');
      const characterKey = Object.keys(categoryData).find(key => {
        const nk = key.trim().normalize('NFC');
        return nk === nc || nk.replace(/\s/g, '') === nc.replace(/\s/g, '');
      });
      if (!characterKey) return null;
      const characterData = categoryData[characterKey];
      const ns = String(sceneType || '').trim().normalize('NFC');
      const sceneKey = Object.keys(characterData).find(key => {
        const nk = key.trim().normalize('NFC');
        return nk === ns || nk.replace(/\s/g, '') === ns.replace(/\s/g, '');
      });
      if (!sceneKey) return null;

      const rawNumbers = characterData[sceneKey];
      const numbers = Array.isArray(rawNumbers)
        ? rawNumbers
        : (Number.isFinite(Number(rawNumbers)) && Number(rawNumbers) > 0
          ? Array.from({ length: Math.floor(Number(rawNumbers)) }, (_, index) => index + 1)
          : []);
      return { characterKey, sceneKey, numbers, maxNumber: numbers.length };
