        try { unlocked = JSON.parse(localStorage.getItem('unlocked_cg') || '{}') || {}; } catch (e) {}
        if (!unlocked[entry.characterKey]) unlocked[entry.characterKey] = {};
        const previous = Number(unlocked[entry.characterKey][entry.sceneKey]) || 0;
        if (previous < entry.maxNumber) {
          unlocked[entry.characterKey][entry.sceneKey] = entry.maxNumber;
          try { localStorage.setItem('unlocked_cg', JSON.stringify(unlocked)); } catch (e) {}
        }
        // 即使正文自己的 localStorage 已记录，也继续通知 HUD，补齐旧版本漏掉的跨域同步。
