    // ==================== 商店交易辅助函数（第一阶段：仅读取/发送） ====================
        function merchantParseNumber(input) {
          if (input === null || input === undefined) return 0;
          const txt = String(input).replace(/,/g, '');
          const m = txt.match(/-?\d+(?:\.\d+)?/);
          return m ? Number(m[0]) : 0;
        }

        function merchantFormatCompactChineseNumber(value) {
          const num = Number(value);
          if (!Number.isFinite(num)) return String(value ?? '0');

          const absNum = Math.abs(num);
          const trimDecimals = function (number, digits) {
            return Number(number).toFixed(digits)
              .replace(/(\.\d*?)0+$/, function (_, decimals) { return decimals; })
              .replace(/\.$/, '');
          };
          if (absNum < 1000000) return String(num);

          const sign = num < 0 ? '-' : '';
          const parts = [];
          const push = function (text) { parts.push(String(text)); };
          const pushThousandRemainder = function (remainder) {
            if (remainder <= 0) return;
            push(trimDecimals(remainder / 1000, 2) + '千');
          };

          if (absNum < 100000000) {
            const wan = Math.floor(absNum / 10000);
            const remainder = absNum % 10000;
            push(sign + String(wan) + '万');
            pushThousandRemainder(remainder);
            return parts.join('');
          }

          let remaining = absNum;
          const yi = Math.floor(remaining / 100000000);
          remaining %= 100000000;
          push(sign + String(yi) + '亿');

          const wan = Math.floor(remaining / 10000);
          remaining %= 10000;
          if (wan > 0) push(String(wan) + '万');
          pushThousandRemainder(remaining);

          return parts.join('');
        }

        function merchantFormatDisplayPrice(input) {
          if (input === null || input === undefined) return '0';
          const raw = String(input).replace(/,/g, '').replace(/G/gi, '').trim();
          const match = raw.match(/-?\d+(?:\.\d+)?/);
          if (!match) return raw || '???';
          return merchantFormatCompactChineseNumber(Number(match[0]));
        }

        function merchantGetPlayerGold() {
          const data = fetchLatestMvuData() || {};
          const person = data.人物 || {};
          const bag = person.背包 || {};
          const fromBag = merchantParseNumber(bag.通用币);
          if (fromBag > 0) return fromBag;
          return merchantParseNumber(person.通用币);
        }

        function merchantIsTrueLike(v) {
          if (v === true || v === 1) return true;
          if (typeof v === 'string') {
            const t = v.trim().toLowerCase();
            return t === 'true' || t === '1' || t === '是' || t === 'yes' || t === 'y';
          }
          return false;
        }

        function merchantNormalizeBagItemType(rawType) {
          const t = String(rawType || '').trim();
          if (t === '任务道具') return '任务物品';
          if (!t) return '杂物';
          if (t.includes('任务')) return '任务物品';
          if (t.includes('唯一')) return '唯一物品';
          if (t.includes('消耗')) return '消耗品';
          if (t.includes('材料')) return '材料';
          if (t.includes('杂')) return '杂物';
          return '杂物';
        }

        function merchantGetSellableEquipments() {
          const data = fetchLatestMvuData() || {};
          const person = data.人物 || {};
          const sellables = [];

          // 装备：兼容 record/object 与 array 两种结构
          const equips = person.装备列表;
          const equipEntries = Array.isArray(equips)
            ? equips.map(function (item, i) { return [String(i), item]; })
            : (equips && typeof equips === 'object' ? Object.entries(equips) : []);

          for (let i = 0; i < equipEntries.length; i++) {
            const pair = equipEntries[i];
            const equipId = pair[0];
            const item = pair[1];
            if (!item || typeof item !== 'object') continue;
            if (!merchantIsTrueLike(item.装备箱)) continue;
            sellables.push({
              __sellKey: 'equip:' + String(equipId),
              __sellKind: '装备',
              名称: item.名称 || equipId,
              品质: item.品质,
              稀有度: item.稀有度,
              类型: item.类型,
              部位: item.部位,
              等级: item.等级,
              数量: 1
            });
          }

          // 背包道具：人物.背包.道具
          const bag = person.背包 || {};
          const bagItems = (bag.道具 && typeof bag.道具 === 'object') ? bag.道具 : {};
          Object.entries(bagItems).forEach(function (pair) {
            const itemName = pair[0];
            const item = pair[1];
            if (!item || typeof item !== 'object') return;
            const qty = merchantParseNumber(item.数量);
            if (qty <= 0) return;
            const itemType = merchantNormalizeBagItemType(item.类型);
            // 出售页仅显示：消耗品/材料/杂物，隐藏任务/唯一
            if (itemType === '任务物品' || itemType === '唯一物品') return;
            if (!['消耗品', '材料', '杂物'].includes(itemType)) return;
            sellables.push({
              __sellKey: 'bag:' + String(itemName),
              __sellKind: '道具',
