        function rpgSplitOutsideBrackets(text, separators) {
          const source = String(text || '');
          const sepSet = new Set(Array.isArray(separators) ? separators : [separators]);
          const parts = [];
          let depth = 0;
          let current = '';
          for (const ch of source) {
            if (ch === '[' || ch === '【' || ch === '(' || ch === '（') {
              depth += 1;
              current += ch;
              continue;
            }
            if ((ch === ']' || ch === '】' || ch === ')' || ch === '）') && depth > 0) {
              depth -= 1;
              current += ch;
              continue;
            }
            if (depth === 0 && sepSet.has(ch)) {
              const trimmed = current.trim();
              if (trimmed) parts.push(trimmed);
              current = '';
              continue;
