        // ===== 提取额外字段（不在已知列表中的字段，按行原样显示） =====
        function rpgExtractExtraFields(raw, knownFields) {
          const decoded = raw.replace(/&gt;/g, '>').replace(/&lt;/g, '<').replace(/&amp;/g, '&');
          const lines = decoded.split('\n');
          const extras = [];
          for (const line of lines) {
            const trimmed = line.trim();
            // 跳过 "- " 开头的续行（技能、攻击力等多行字段的子项）
            if (/^\s*-\s+/.test(line)) continue;
            const m = trimmed.match(/^([^\s\-].+?):\s*(.+)$/);
            if (!m) continue;
            const fieldName = m[1].trim();
            if (knownFields.includes(fieldName)) continue;
            extras.push({ label: fieldName, value: m[2].trim() });
          }
          return extras;
        }
        function rpgRenderExtraFields(extras) {
          if (!extras.length) return '';
          return extras.map(e =>
            `<div class="flex items-start gap-2 text-xs font-noto py-1" style="color:#4a3a2a;"><span class="font-bold flex-shrink-0" style="color:#6a5a4a;">${rpgEsc(e.label)}:</span><span>${rpgEsc(e.value)}</span></div>`
          ).join('');
        }

        // ===== COMBAT CARD RENDERER =====
        function renderRpgDiceCombat(raw, idx) {
          const char = rpgParseField(raw, '角色'), action = rpgParseField(raw, '动作'), target = rpgParseField(raw, '目标');
