              <div class="rounded px-3 py-2 text-xs font-mono font-semibold" style="background:rgba(0,0,0,0.05);color:#2a1a0a;">${rpgDiceIcon(dice)}</div>
              <div class="flex items-center gap-2">
                ${isCrit ? '<span class="text-xs px-2 py-0.5 rounded font-bold badge-glow-danger" style="background:rgba(139,37,0,0.1);border:1px solid rgba(139,37,0,0.25);color:#8b2500;"><i class="fa-solid fa-burst mr-1" style="font-size:9px;"></i>暴击</span>' : result.includes('[命中]') ? '<span class="text-xs px-2 py-0.5 rounded font-bold badge-glow-success" style="background:rgba(45,106,46,0.1);border:1px solid rgba(45,106,46,0.25);color:#2d6a2e;"><i class="fa-solid fa-crosshairs mr-1" style="font-size:9px;"></i>命中</span>' : ''}
                ${dmgNum ? '<span class="font-bold text-base" style="color:#8b2500;">' + dmgNum + '</span>' : ''}
