        // ===== INITIATIVE CARD RENDERER =====
        function renderRpgInitiative(raw, idx) {
          const decoded = decodeHtmlEntities(String(raw || '')).replace(/&nbsp;/gi, ' ');
          const axis = rpgParseField(raw, '行动轴');
          const narration = rpgParseField(raw, '特图的旁白');
          // 逐行解析先攻掷骰（排除 行动轴 / 特图的旁白 字段）
          const rolls = [];
          decoded.split('\n').forEach(rawl => {
            const line = rawl.trim(); if (!line) return;
            const m = line.match(/^(.+?)\s*[:：]\s*(.+)$/);
            if (!m) return;
            const key = m[1].trim(), val = m[2].trim();
            if (key === '行动轴' || key === '特图的旁白') return;
            const totalMatch = val.match(/=\s*(-?\d+)/);
            const total = totalMatch ? totalMatch[1] : '';
            const d20Match = val.match(/d20\s*\[\s*(\d+)\s*\]/i);
            const d20 = d20Match ? d20Match[1] : '';
            const expr = val.replace(/\s*=\s*-?\d+\s*$/, '');
            rolls.push({ name: key, expr, total, d20 });
          });
          // 最高先攻用于高亮
          const maxTotal = rolls.reduce((mx, r) => Math.max(mx, parseInt(r.total, 10) || -Infinity), -Infinity);
          // 按总值降序得到先攻排名
          const orderRank = rolls
            .map((r, i) => ({ i, total: parseInt(r.total, 10) }))
            .sort((a, b) => (isNaN(b.total) ? -Infinity : b.total) - (isNaN(a.total) ? -Infinity : a.total))
            .reduce((acc, item, idx) => { acc[item.i] = idx + 1; return acc; }, {});
          const rollHtml = rolls.map((r, i) => {
            const isTop = (parseInt(r.total, 10) === maxTotal) && r.total !== '';
            const rank = orderRank[i] || (i + 1);
            return '<div class="init-roll' + (isTop ? ' init-top' : '') + '">'
              + '<span class="init-rank">' + rank + '</span>'
              + '<span class="init-name">' + rpgEsc(r.name) + '</span>'
              + '<span class="init-expr">' + rpgDiceIcon(rpgEsc(r.expr)) + '</span>'
