            + '<div class="combat-header px-4 py-3 relative"><div class="flex items-center gap-2 relative z-10">'
            + '<i class="fa-solid fa-dice-d20 text-xs" style="color:#8b7a2f88;"></i>'
            + '<span class="text-xs tracking-wider uppercase font-cinzel_body" style="color:#8b7a2f88;">Initiative</span>'
            + '<h3 class="font-noto font-bold text-base ml-1" style="color:#1a1408;">先攻检定</h3>'
