                  + '<div class="font-cinzel_body text-xs font-bold mb-2" style="color:#a8a090;"><i class="fa-solid fa-hand-fist mr-1" style="color:#c0392b;"></i>ATTACK</div>'
                  + atkItems + '</div>';
              }
              // 单行基础攻击格式
              if (baseAtk) {
                return '<div class="text-sm font-noto font-bold mb-3" style="color:#3a2a1a;"><i class="fa-solid fa-hand-fist mr-1" style="color:#c0392b;"></i>基础攻击: ' + rpgEsc(baseAtk) + (tierCoef ? ' <span style="color:#a8a090;font-weight:normal;font-size:11px">| ' + rpgEsc(tierCoef) + '</span>' : '') + '</div>';
              }
              return '';
            })()}
            ${skillsHtml ? `<div class="mb-3" style="border-top:1px solid rgba(180,160,120,.2);padding-top:12px"><div class="font-cinzel_body text-xs font-bold mb-2" style="color:#a8a090;"><i class="fa-solid fa-wand-sparkles mr-1"></i>SKILLS</div>${skillsHtml}</div>` : ''}
            ${traits ? `<div class="text-sm font-noto font-bold mb-3" style="color:#3a2a1a;"><i class="fa-solid fa-eye mr-1" style="color:#a8a090;"></i>特长: ${rpgEsc(traits)}</div>` : ''}
            ${(weakList.length || resistList.length) ? `<div class="flex flex-wrap gap-2 mb-3">${weakList.map(w => `<span class="weakness-badge"><i class="fa-solid fa-heart-crack" style="color:#c0392b"></i>${rpgEsc(w)}</span>`).join('')}${resistList.map(r => `<span class="resistance-badge"><i class="fa-solid fa-shield-halved" style="color:#4a4a6a"></i>${rpgEsc(r)}</span>`).join('')}</div>` : ''}
            ${enemyExtraHtml ? `<div class="mb-3 px-1">${enemyExtraHtml}</div>` : ''}
            </div>
            ${narr ? `<div class="pt-3" style="border-top:1px solid rgba(180,160,120,.15);background:rgba(244,236,225,.3);padding:12px 20px;border-radius:0 0 6px 6px;"><div class="narration-wrap"><i class="fa-solid fa-feather-pointed narr-icon" style="color:#c2a878;"></i><span class="narration-quote italic font-noto" style="color:#3a2a1a;">${rpgEsc(narr)}</span></div></div>` : ''}
            </div></div>`;
        }

        // ===== SUMMON CARD RENDERER =====
        function renderRpgSummonOverview(raw, idx) {
          const name = rpgParseField(raw, '召唤物'), source = rpgParseField(raw, '来源'), statusLine = rpgParseField(raw, '状态');
          const skillRatio = rpgParseField(raw, '技能倍率'), duration = rpgParseField(raw, '持续时间');
          const narr = rpgParseField(raw, '特图的旁白');
          const summonKnown = ['召唤物', '来源', '状态', '技能倍率', '持续时间', '特图的旁白'];
          const summonExtra = rpgExtractExtraFields(raw, summonKnown);
          const summonExtraHtml = rpgRenderExtraFields(summonExtra);
          const hpM = statusLine.match(/HP\s*(\d+)\/(\d+)/);
          const hpCur = hpM ? parseInt(hpM[1]) : 0, hpMax = hpM ? parseInt(hpM[2]) : 1, hpPct = (hpCur / hpMax * 100);
          const acM = statusLine.match(/AC\s*(\d+)/), ac = acM ? acM[1] : '';
          const isCluster = name.includes('|');
          const count = isCluster ? name.split('|').length : 1;
          const headerText = isCluster ? '召唤物集群' : '召唤降临';
          const headerIcon = isCluster ? 'fa-users' : 'fa-hat-wizard';
          return `<div class="log-card summon-card card-animate" style="animation-delay:${idx * 0.08}s;padding:0">
            <div class="relative z-10">
            <div class="summon-card-header"><span class="summon-card-header-line"></span><i class="fa-solid ${headerIcon} header-icon"></i><span class="summon-card-header-text">${headerText}</span><i class="fa-solid ${headerIcon} header-icon"></i><span class="summon-card-header-line"></span></div>
            <div class="px-5 py-4">
            <div class="flex items-start gap-3 mb-3"><div class="summon-icon-frame"><i class="fa-solid ${isCluster ? 'fa-users' : 'fa-dragon'}"></i></div><div class="flex-1 min-w-0"><h3 class="font-noto text-base font-bold" style="color:#1a2a3a">${rpgEsc(name)}</h3>${source ? `<div class="text-xs font-noto mt-0.5" style="color:#6a8aaa"><i class="fa-solid fa-wand-sparkles mr-1"></i>${rpgEsc(source)}</div>` : ''}</div>${count > 1 ? `<div class="flex items-center gap-1 flex-shrink-0"><span class="inline-block px-2 py-0.5 rounded text-xs font-bold" style="background:rgba(41,128,185,.1);border:1px solid rgba(41,128,185,.2);color:#1a3a5a">×${count}</span></div>` : ''}</div>
            ${hpM ? `<div class="flex items-center justify-between mb-1"><span class="font-noto text-xs font-bold" style="color:#1a2a3a;opacity:.6">HP</span><span class="font-noto text-xs font-bold" style="color:#1a2a3a">${hpCur} / ${hpMax}</span></div>
            <div class="summon-hp-bar mb-2"><div class="summon-hp-fill" style="width:${hpPct}%"></div></div>` : ''}
            <div class="flex items-center justify-between mb-3"><span class="font-noto text-xs" style="color:#1a2a3a;opacity:.6">${ac ? `<i class="fa-solid fa-shield-halved mr-1"></i>AC <strong>${rpgEsc(ac)}</strong>` : ''}</span>${duration ? `<span class="font-noto text-xs" style="color:#6a8aaa"><i class="fa-regular fa-clock mr-1"></i>${rpgEsc(duration)}</span>` : ''}</div>
            ${skillRatio ? `<div class="text-sm font-noto font-bold mb-2" style="color:#1a3a5a"><i class="fa-solid fa-fire mr-1" style="color:#2980b9"></i>技能倍率: ${rpgEsc(skillRatio)}</div>` : ''}
            ${summonExtraHtml ? `<div class="mb-2 px-1">${summonExtraHtml}</div>` : ''}
            </div>
            ${narr ? `<div class="pt-3" style="border-top:1px solid rgba(120,160,200,.15);background:rgba(225,238,250,.3);padding:12px 20px;border-radius:0 0 6px 6px;"><div class="narration-wrap"><i class="fa-solid fa-feather-pointed narr-icon" style="color:#80b8d8;"></i><span class="narration-quote italic font-noto" style="color:#1a2a3a;">${rpgEsc(narr)}</span></div></div>` : ''}
            </div></div>`;
        }

        // ===== LOOT CARD RENDERER =====
        function normalizeQualityName(value) {
          return value === '神器' ? '卓越' : value;
        }

        // 解析掉落物条目，支持: "名称 x数量 品质" / "名称 x数量 (品质)" / "名称 x数量 [品质]"
        function parseLootItems(fieldStr, isEquip) {
          if (!fieldStr || fieldStr === '无') return [];
          const rarityClsMap = { '普通': 'item-common', '精良': 'item-fine', '稀有': 'item-rare', '卓越': 'item-artifact', '传说': 'item-legendary', '史诗': 'item-epic', '神话': 'item-mythic' };
          const shimmerClsMap = { '卓越': 'item-shimmer-artifact', '传说': 'item-shimmer-legendary', '史诗': 'item-shimmer-epic', '神话': 'item-shimmer-mythic' };
          return fieldStr.split(/,|，/).map(i => {
            const s = i.trim(); if (!s) return null;
            // 匹配: 名称 x数量 后跟 (品质) 或 [品质] 或 裸品质
            const m = s.match(/^(.+?)\s+x(\d+)\s*(?:[\(（\[【]([^）\)\]】]+)[\)）\]】]|(\S+))\s*$/);
            if (m) { const rarity = normalizeQualityName((m[3] || m[4] || '普通').trim()); return { name: m[1].trim(), count: m[2], rarity, cls: rarityClsMap[rarity] || 'item-common', shimmerCls: shimmerClsMap[rarity] || '', isEquip: !!isEquip }; }
            // fallback: 尝试只有名称+品质括号，无数量
            const m2 = s.match(/^(.+?)\s*(?:[\(（\[【]([^）\)\]】]+)[\)）\]】])\s*$/);
            if (m2) { const rarity = normalizeQualityName(m2[2].trim()); return { name: m2[1].trim(), count: '1', rarity, cls: rarityClsMap[rarity] || 'item-common', shimmerCls: shimmerClsMap[rarity] || '', isEquip: !!isEquip }; }
            return { name: s, count: '1', rarity: '普通', cls: 'item-common', shimmerCls: '', isEquip: !!isEquip };
          }).filter(Boolean);
        }

        function renderRpgLootLog(raw, idx) {
          const source = rpgParseField(raw, '来源'), qualityRaw = rpgParseField(raw, '品质'), dice = rpgParseField(raw, '骰运');
          const itemsRaw = rpgParseField(raw, '物品'), equipRaw = rpgParseField(raw, '装备');
          const gold = rpgParseField(raw, '通用币'), material = rpgParseField(raw, '材料');
          const special = rpgParseField(raw, '特殊掉落'), narration = rpgParseField(raw, '特图的旁白');
          const lootKnown = ['来源', '品质', '骰运', '物品', '装备', '通用币', '材料', '特殊掉落', '特图的旁白'];
          const lootExtra = rpgExtractExtraFields(raw, lootKnown);
          const lootExtraHtml = rpgRenderExtraFields(lootExtra);
          // 从品质字段提取品质关键词和详情注释
          const qualityKeywords = ['神话', '史诗', '传说', '卓越', '神器', '稀有', '精良', '普通'];
          let matchedQuality = '普通', qualityDetail = '';
          for (const q of qualityKeywords) { if (qualityRaw.includes(q)) { matchedQuality = q; break; } }
          const quality = normalizeQualityName(matchedQuality);
          const qDetailRaw = qualityRaw.replace(new RegExp('^\\s*' + matchedQuality + '\\s*'), '').trim();
          if (qDetailRaw) qualityDetail = qDetailRaw;
          const qualityClassMap = { '普通': 'quality-common', '精良': 'quality-fine', '稀有': 'quality-rare', '卓越': 'quality-artifact', '传说': 'quality-legendary', '史诗': 'quality-epic', '神话': 'quality-mythic' };
          const qualityClass = qualityClassMap[quality] || 'quality-common';
          const qualityColor = { '普通': '#2D3436', '精良': '#0047AB', '稀有': '#9b59b6', '卓越': '#e84393', '传说': '#e67e22', '史诗': '#C9A227', '神话': '#e8198b' };
          const qualityIcon = { '普通': 'fa-circle', '精良': 'fa-star-half-stroke', '稀有': 'fa-star', '卓越': 'fa-gem', '传说': 'fa-crown', '史诗': 'fa-sun', '神话': 'fa-infinity' };
          const qColor = qualityColor[quality] || '#2D3436';
          const isHighTier = ['卓越', '传说', '史诗', '神话'].includes(quality);
          // 合并物品+装备列表
          const itemList = [...parseLootItems(itemsRaw, false), ...parseLootItems(equipRaw, true)];
          const sparkles = isHighTier ? Array.from({ length: 8 }, (_, i) => `<div class="sparkle" style="left:${10 + Math.random() * 80}%;top:${20 + Math.random() * 60}%;animation-delay:${i * 0.4}s;animation-duration:${2 + Math.random() * 2}s;background:${qColor};"></div>`).join('') : '';
          const brightColor = { '普通': '#c8bfb0', '精良': '#70b0e8', '稀有': '#d0a8f0', '卓越': '#f898cc', '传说': '#f0b060', '史诗': '#e8d068', '神话': '#f870b8' };
          // 品质详情行
          const qualityDetailHtml = qualityDetail ? `<div class="text-xs px-3 py-1.5 mb-3 rounded" style="color:${qColor};opacity:0.75;background:rgba(0,0,0,0.15);line-height:1.6;word-break:break-all;"><i class="fa-solid fa-scroll" style="font-size:9px;margin-right:4px;"></i>${qualityDetail}</div>` : '';
          // 骰运详情：分离结果摘要和判定过程
          const diceMain = dice.replace(/\|/g, '<span style="opacity:0.4;margin:0 6px;">|</span>');
          return `<div class="log-card card-loot ${qualityClass} card-animate" style="animation-delay:${idx * 0.08}s">
            ${sparkles}<div class="loot-clasp"></div>
            <div class="px-4 pt-2 pb-3 relative z-10">
              <div class="flex items-center justify-between mb-3 mt-2"><div><div class="flex items-center gap-2 mb-1"><i class="fa-solid fa-box-open text-amber_warm/70 text-xs"></i><span class="text-xs text-amber_warm/60 font-cinzel_body tracking-wider uppercase">战利品</span></div><div class="text-sm text-white font-noto font-semibold">${source}</div></div><span class="inline-flex items-center gap-1 px-2 py-0.5 rounded text-xs font-cinzel_body" style="background:${qColor}18;border:1px solid ${qColor}55;color:${qColor};"><i class="fa-solid ${qualityIcon[quality] || 'fa-circle'}" style="font-size:10px;"></i>${quality}</span></div>
              ${qualityDetailHtml}
              <div class="bg-black/20 rounded px-3 py-1.5 text-xs text-amber_warm/70 font-mono mb-3" style="line-height:1.6;">${rpgDiceIcon(diceMain)}</div>
              <div class="space-y-1.5 mb-3">${itemList.map(it => { const txtColor = brightColor[it.rarity] || '#c8bfb0'; const isShimmer = !!it.shimmerCls; const icon = it.isEquip ? 'fa-shield-halved' : 'fa-gem'; return `<div class="flex items-center justify-between bg-black/15 rounded px-3 py-1.5${it.isEquip ? ' border-l-2' : ''}" style="${it.isEquip ? 'border-left-color:' + txtColor + ';' : ''}"><span class="flex items-center gap-1.5"><i class="fa-solid ${icon} text-xs" style="color:${txtColor};"></i><span class="text-xs font-bold ${isShimmer ? it.shimmerCls : ''}" style="${isShimmer ? '' : 'color:' + txtColor + ';'}">${it.name}</span></span><div class="flex items-center gap-2"><span class="text-xs text-white/50">x${it.count}</span><span class="text-xs px-1.5 py-0.5 rounded font-bold" style="background:rgba(255,255,255,0.06);color:${txtColor};border:1px solid rgba(255,255,255,0.1);font-size:10px;">${it.rarity}</span></div></div>`; }).join('')}</div>
              <div class="flex items-center gap-4 mb-2">${gold ? `<span class="flex items-center gap-1 text-sm"><i class="fa-solid fa-coins text-yellow-500"></i><span class="text-white font-bold">${gold}</span></span>` : ''}${material && material !== '无' ? `<span class="flex items-center gap-1 text-xs text-amber_warm/60"><i class="fa-solid fa-cubes-stacked"></i>${material}</span>` : ''}</div>
              ${special && special !== '无' ? `<div class="bg-yellow-500/10 border border-yellow-500/20 rounded px-3 py-2 text-xs" style="color:#e8c87e;"><i class="fa-solid fa-sparkles mr-1"></i>${special}</div>` : ''}
              ${lootExtraHtml ? `<div class="mt-2 px-1 loot-extra-fields">${lootExtraHtml}</div>` : ''}
            </div>
            ${narration ? `<div class="loot-narration px-4 py-3" style="background:rgba(255,250,240,.08);"><div class="narration-wrap"><i class="fa-solid fa-feather-pointed narr-icon" style="color:#c8a45e;"></i><span class="narration-quote italic" style="color:#ede0c8;">${narration}</span></div></div>` : ''}
          </div>`;
        }

        // ===== EXPERIENCE LOG CARD RENDERER =====
        function renderRpgExperienceLog(raw, idx) {
          const source = rpgParseField(raw, '来源'), detail = rpgParseField(raw, '明细');
          // 支持"本次获得"或"总获得"字段
          let gained = rpgParseField(raw, '本次获得');
          if (!gained || gained.trim() === '') gained = rpgParseField(raw, '总获得');
          const progress = rpgParseField(raw, '当前进度');
          const proficiency = rpgParseField(raw, '熟练度进度');
          const narration = rpgParseField(raw, '特图的旁白');
          const expKnown = ['来源', '明细', '本次获得', '总获得', '当前进度', '熟练度进度', '特图的旁白'];
          const expExtra = rpgExtractExtraFields(raw, expKnown);
          const expExtraHtml = rpgRenderExtraFields(expExtra);
          // 提取经验值数字（支持 +123 或 123 格式）
          const expMatch = gained.match(/[+]?(\d+)/), expGained = expMatch ? expMatch[1] : '0';
          // 支持多种进度格式：
          // 格式A: "12200/5000 | 触发升级判定"  或 "3200/5000"
          // 格式B: "3200/5000 45% Lv.5 还需 1800"（旧格式）
          // 格式C: "距离 Lv.2 还需 18 EXP"（仅文本格式）
          const progSimple = progress.match(/(\d+)\s*\/\s*(\d+)/);
          const progPctExplicit = progress.match(/(\d+)%/);
          let progCur = 0, progMax = 1, progPct = 0;
          if (progSimple) {
            progCur = parseInt(progSimple[1]); progMax = parseInt(progSimple[2]);
            if (progMax > 0) progPct = Math.min(Math.round(progCur / progMax * 100), 100);
          }
          if (progPctExplicit) progPct = parseInt(progPctExplicit[1]);
          const isLevelUp = progCur >= progMax && progMax > 0;
          // 进度条后的附加文本（如 "触发升级判定"）
          const progNote = progress.replace(/[\d\s\/|%]+/g, '').trim();
          const lvlMatch = progress.match(/Lv\.(\d+)/), nextLvl = lvlMatch ? lvlMatch[1] : '';
          const remainMatch = progress.match(/还需\s*(\d+)/), remaining = remainMatch ? remainMatch[1] : '';
          // 底部提示行
          let footerHtml = '';
          if (isLevelUp) {
            footerHtml = `<div class="flex items-center justify-center mt-2"><span class="inline-flex items-center gap-1 px-3 py-1 rounded-full text-xs font-bold" style="background:rgba(139,105,20,0.15);color:#8B6914;"><i class="fa-solid fa-arrow-up mr-1"></i>${progNote || '触发升级判定'}</span></div>`;
          } else if (nextLvl && remaining) {
            footerHtml = `<div class="flex items-center justify-between mt-2"><span class="text-xs" style="color:#7a7a7a;"><i class="fa-solid fa-arrow-trend-up mr-1" style="color:#8B6914;"></i>距离 Lv.${nextLvl} 还需 ${remaining} EXP</span></div>`;
          } else if (progNote) {
            footerHtml = `<div class="flex items-center justify-center mt-2"><span class="text-xs" style="color:#7a7a7a;">${progNote}</span></div>`;
          }
          // 构建进度条部分（如果有进度数据则显示）
          let progressBarHtml = '';
          if (progSimple) {
            progressBarHtml = `<div class="px-6 pb-6"><div class="flex items-center justify-between mb-2"><span class="text-xs font-medium" style="color:#7a7a7a;">进度</span><span class="text-xs font-bold" style="color:#1a1a1a;">${progCur} / ${progMax} <span style="color:#8B6914;">(${progPct}%)</span></span></div><div class="h-3 rounded-full overflow-hidden" style="background:#f0ede8;"><div class="h-full rounded-full exp-bar-fill" style="--exp-target:${isLevelUp ? 100 : progPct}%;background:linear-gradient(90deg,${isLevelUp ? '#d4a020,#e8c040,#f0d860' : '#8B6914,#a8842a,#c4a23a'});"></div></div>${footerHtml}</div>`;
          } else if (footerHtml) {
            // 没有进度条但有footer信息（如"距离 Lv.2 还需 18 EXP"）
            progressBarHtml = `<div class="px-6 pb-4">${footerHtml}</div>`;
          }
          // 熟练度进度渲染
          let profHtml = '';
          if (proficiency) {
            // 解析格式: "+3 剑术 (目前阶位: 学徒)" 或 "+5 烹饪 (目前阶位: 熟手)"
            const profMatch = proficiency.match(/([+\-]?\d+)\s*(.+?)\s*\(目前阶位[:：]\s*(.+?)\)/);
            if (profMatch) {
              const profVal = profMatch[1], profName = profMatch[2], profTier = profMatch[3];
              profHtml = `<div class="flex items-center gap-2 text-xs py-1" style="color:#4a3a2a;"><span class="font-bold flex-shrink-0" style="color:#8B6914;"><i class="ra ra-muscle-up mr-1"></i>熟练度:</span><span class="font-semibold">${rpgEsc(profVal)} ${rpgEsc(profName)}</span><span style="color:#6a5a4a;">(${rpgEsc(profTier)})</span></div>`;
            } else {
              profHtml = `<div class="flex items-center gap-2 text-xs py-1" style="color:#4a3a2a;"><span class="font-bold flex-shrink-0" style="color:#8B6914;"><i class="ra ra-muscle-up mr-1"></i>熟练度:</span><span>${rpgEsc(proficiency)}</span></div>`;
            }
          }
          return `<div class="log-card card-exp card-animate" style="animation-delay:${idx * 0.08}s">
            <div class="px-6 py-4 flex items-center gap-3" style="background:linear-gradient(135deg,rgba(139,105,20,0.06) 0%,rgba(139,105,20,0.02) 100%);">
              <div class="w-10 h-10 rounded-lg flex items-center justify-content" style="background:rgba(139,105,20,0.12);display:flex;align-items:center;justify-content:center;"><i class="ra ra-trophy text-lg" style="color:#8B6914;"></i></div>
              <div class="flex-1"><div class="text-xs font-medium tracking-wide uppercase" style="color:#8B6914;font-family:'Inter',sans-serif;">Experience Gained</div><div class="text-sm" style="color:#4a4a4a;">${source}</div></div>
            </div>
            <div class="px-6 py-6 text-center"><div class="damage-pop inline-block"><span class="font-black text-5xl" style="color:#1a1a1a;font-family:'Noto Serif SC',serif;">+${expGained}</span><span class="text-lg font-bold ml-2" style="color:#8B6914;">EXP</span></div>${detail ? `<div class="text-sm mt-2" style="color:#7a7a7a;">${detail}</div>` : ''}</div>
            ${progressBarHtml}
            ${profHtml || expExtraHtml ? `<div class="px-6 pb-3">${profHtml}${expExtraHtml}</div>` : ''}
            ${narration ? `<div class="combat-narration px-4 py-3"><div class="narration-wrap"><i class="fa-solid fa-feather-pointed narr-icon" style="color:#c8a45e;"></i><span class="narration-quote italic font-medium" style="color:#3a2a1a;">${narration}</span></div></div>` : ''}
          </div>`;
        }

        // ===== QUEST CONTRACT CARD RENDERER =====
        function renderRpgQuestContract(raw, idx) {
          const quest = rpgParseField(raw, '任务'), client = rpgParseField(raw, '委托方'), level = rpgParseField(raw, '等级');
          const intro = rpgParseField(raw, '简介'), goal = rpgParseField(raw, '目标'), reward = rpgParseField(raw, '奖励'), delivery = rpgParseField(raw, '交付');
          const status = rpgParseField(raw, '状态'), nextStep = rpgParseField(raw, '下一步');
          const narration = rpgParseField(raw, '特图的旁白');
          const questKnown = ['任务', '委托方', '等级', '简介', '目标', '奖励', '交付', '状态', '下一步', '特图的旁白'];
          const questExtra = rpgExtractExtraFields(raw, questKnown);
          const questExtraHtml = rpgRenderExtraFields(questExtra);
          const diffMatch = level.match(/难度[：:]\s*(\S+)/), diff = diffMatch ? diffMatch[1] : '';
          const recMatch = level.match(/(推荐\s*\S+)/), recLevel = recMatch ? recMatch[1] : '';
          const progMatch = goal ? goal.match(/\((\d+)\/(\d+)\)/) : null;
          const isComplete = progMatch && parseInt(progMatch[1]) >= parseInt(progMatch[2]);
          const teamNoteMatch = reward ? reward.match(/\(团队注:.*?\)/) : null;
          const teamNote = teamNoteMatch ? teamNoteMatch[0] : '';
          const mainReward = reward ? reward.replace(/\s*\(团队注:.*?\)/, '').trim() : '';
          // 构建各section，仅非空时渲染
          let sections = '';
          if (quest && quest.trim()) sections += `<div class="quest-section"><div class="quest-section-label"><i class="ra ra-scroll-unfurled mr-1"></i>任务名称</div><div class="brush-font text-2xl tracking-wide">${quest}</div></div>`;
          if (client && client.trim()) sections += `<div class="quest-section"><div class="quest-section-label"><i class="ra ra-player mr-1"></i>委托方</div><div class="text-sm">${client}</div></div>`;
          if (recLevel || diff) sections += `<div class="quest-section"><div class="flex items-center gap-4 flex-wrap">${recLevel ? `<div class="flex-shrink-0"><div class="quest-section-label"><i class="ra ra-level-four mr-1"></i>等级</div><div class="text-sm">${recLevel}</div></div>` : ''}${diff ? `<div class="flex items-center gap-2 flex-shrink-0"><div class="quest-section-label">难度</div><div class="quest-rank-badge">${diff}</div></div>` : ''}</div></div>`;
          if (intro && intro.trim()) sections += `<div class="quest-section"><div class="quest-section-label"><i class="ra ra-book mr-1"></i>简介</div><div class="text-sm leading-relaxed" style="color:#4a4a4a;">${intro}</div></div>`;
          if (goal && goal.trim()) sections += `<div class="quest-section"><div class="quest-section-label"><i class="ra ra-crossed-swords mr-1"></i>目标</div><div class="text-sm font-bold">${goal}</div></div>`;
          if (mainReward) sections += `<div class="quest-section"><div class="quest-section-label"><i class="ra ra-gold-bar mr-1"></i>奖励</div><div class="quest-reward-text">${mainReward}</div>${teamNote ? `<div class="text-xs mt-1" style="color:#8a8a8a;">${teamNote}</div>` : ''}</div>`;
          if (delivery && delivery.trim()) sections += `<div class="quest-section"><div class="quest-section-label"><i class="ra ra-compass mr-1"></i>交付</div><div class="text-xs" style="color:#4a4a4a;">${delivery}</div></div>`;
          if (status && status.trim()) sections += `<div class="quest-section"><div class="quest-section-label"><i class="ra ra-flag mr-1"></i>状态</div><div class="text-sm font-semibold" style="color:#2a6e3f;">${status}</div></div>`;
          if (nextStep && nextStep.trim()) sections += `<div class="quest-section"><div class="quest-section-label"><i class="ra ra-footprint mr-1"></i>下一步</div><div class="text-sm" style="color:#4a4a4a;">${nextStep}</div></div>`;
          return `<div class="log-card card-quest-3 card-animate" style="animation-delay:${idx * 0.08}s">
            <div class="quest-banner"><span class="quest-cloud-left"></span><i class="ra ra-scroll-unfurled mr-2"></i>委托契约<span class="quest-cloud-right"></span></div>
            <div class="quest-body-3 relative">
              ${sections}
              ${questExtraHtml ? `<div class="quest-section">${questExtraHtml}</div>` : ''}
              <div class="quest-big-seal">${isComplete ? '已<br>完成' : '已<br>受理'}</div>
            </div>
            ${narration ? `<div class="combat-narration px-4 py-3"><div class="narration-wrap"><i class="fa-solid fa-feather-pointed narr-icon" style="color:#c8a45e;"></i><span class="narration-quote italic font-medium" style="color:#3a2a1a;">${narration}</span></div></div>` : ''}
          </div>`;
        }

        // ===== MERCHANT STORE RENDERER =====
        function merchantStoreScalar(value) {
          if (value === undefined || value === null) return '';
          if (typeof value === 'string') return value.trim();
          if (typeof value === 'number' || typeof value === 'boolean') return String(value);
          if (Array.isArray(value)) return value.map(merchantStoreScalar).filter(Boolean).join(', ');
          return String(value).trim();
        }

        function merchantStoreNormalizeQuality(value) {
          const text = merchantStoreScalar(value);
          const QUALITY_ENUM = ['普通', '精良', '稀有', '卓越', '神器', '传说', '史诗', '神话'];
          for (let i = 0; i < QUALITY_ENUM.length; i++) {
            if (text.includes(QUALITY_ENUM[i])) return normalizeQualityName(QUALITY_ENUM[i]);
          }
          return text;
        }

        function merchantStoreNormalizeTags(value) {
          if (Array.isArray(value)) return value.map(merchantStoreScalar).filter(Boolean);
          const text = merchantStoreScalar(value);
          if (!text || text === '无' || text === '[]') return [];
          return text.replace(/^\[|\]$/g, '').split(/[，,]/).map(function (it) { return it.trim(); }).filter(Boolean);
        }

        function merchantStoreNormalizeAttributes(value) {
          if (value === undefined || value === null || value === '' || value === '无') return {};
          if (typeof value === 'object' && !Array.isArray(value)) return value;
          const text = merchantStoreScalar(value);
          if (!text || text === '{}' || text === '无') return {};
          try {
            if (typeof jsyaml !== 'undefined' && typeof jsyaml.load === 'function') {
              const parsed = jsyaml.load(text);
              if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) return parsed;
            }
          } catch (e) { }
          return text;
        }

        function merchantStoreFormatTags(value) {
          if (Array.isArray(value)) return value.map(merchantStoreScalar).filter(Boolean);
          return merchantStoreNormalizeTags(value);
        }

        function merchantStoreFormatAttributes(value) {
          if (!value || value === '{}' || value === '无') return '无';
          if (typeof value === 'object' && !Array.isArray(value)) {
            const keys = Object.keys(value);
            if (!keys.length) return '无';
            return keys.map(function (k) {
              const attrVal = merchantStoreScalar(value[k]).replace(/^\+/, '');
              return `${k} +${attrVal}`;
            }).join(' / ');
          }
          const attributes = merchantStoreScalar(value);
          if (!attributes || attributes === '{}' || attributes === '无') return '无';
          try {
            if (/^[\d.\s+-]+$/.test(attributes.trim())) return attributes.trim();
            let jsonStr = attributes.replace(/'/g, '"');
            jsonStr = jsonStr.replace(/([{,]\s*)(['"])?([a-zA-Z0-9_\u4e00-\u9fa5]+)(['"])?\s*:/g, function (match, p1, p2, p3) {
              return p1 + '"' + p3 + '":';
            });
            const j = JSON.parse(jsonStr);
            const keys = Object.keys(j);
            if (keys.length > 0) {
              return keys.map(function (k) {
                return `${k} +${String(j[k]).replace(/^\+/, '')}`;
              }).join(' / ');
            }
          } catch (e) {
            const matches = [...attributes.matchAll(/([a-zA-Z\u4e00-\u9fa5]+)\s*[:：]?\s*([a-zA-Z0-9_+.-]+)/g)];
            if (matches.length > 0) {
              return matches.map(function (m) {
                return `${m[1]} +${m[2].replace(/^\+/, '')}`;
              }).join(' / ');
            }
          }
          return attributes;
        }

        function merchantStoreNormalizeItem(rawItem) {
          if (!rawItem || typeof rawItem !== 'object' || Array.isArray(rawItem)) {
            const fallbackName = merchantStoreScalar(rawItem);
            return fallbackName ? { name: fallbackName, props: { 名称: fallbackName } } : null;
          }

          let data = rawItem;
          let wrapperName = '';
          const rawKeys = Object.keys(rawItem);
          if (rawKeys.length === 1) {
            const firstKey = rawKeys[0];
            const firstVal = rawItem[firstKey];
            if (firstVal && typeof firstVal === 'object' && !Array.isArray(firstVal)) {
              data = firstVal;
              if (!['物品名', '商品', '条目', 'item'].includes(firstKey)) wrapperName = merchantStoreScalar(firstKey);
            }
          }

          const props = {};
          Object.keys(data).forEach(function (key) {
            const val = data[key];
            if (key === '标签') {
              props[key] = merchantStoreNormalizeTags(val);
            } else if (key === '属性加成') {
              props[key] = merchantStoreNormalizeAttributes(val);
            } else if (key === '品质') {
              props[key] = merchantStoreNormalizeQuality(val);
            } else {
              props[key] = merchantStoreScalar(val);
            }
          });

          const name = merchantStoreScalar(props['名称']) || wrapperName;
          if (!name) return null;
          props['名称'] = name;
          if (props['标签'] === undefined) props['标签'] = [];
          if (props['属性加成'] === undefined) props['属性加成'] = {};
          if (!merchantStoreScalar(props['数量'])) props['数量'] = '1';
          return { name: name, props: props };
        }

        function merchantStoreNormalizeCategoryObject(rawCategory) {
          if (!rawCategory || typeof rawCategory !== 'object') return null;
          if (Array.isArray(rawCategory)) return null;

          const keys = Object.keys(rawCategory);
          const ITEM_KEYS = new Set(['items', '商品', '条目']);
          const NAME_HINT_KEYS = ['分类', 'name', '名称', 'category', '分类名'];

          let itemsRaw = [];
          let categoryName = '';

          for (let i = 0; i < NAME_HINT_KEYS.length; i++) {
            const key = NAME_HINT_KEYS[i];
            const val = rawCategory[key];
            if (val === undefined || val === null) continue;
            if (typeof val === 'object' && !Array.isArray(val)) continue;
            const text = merchantStoreScalar(val);
            if (text) {
              categoryName = text;
              break;
            }
          }

          for (let i = 0; i < keys.length; i++) {
            const key = keys[i];
            if (ITEM_KEYS.has(key) && Array.isArray(rawCategory[key])) {
              itemsRaw = rawCategory[key];
              break;
            }
          }

          if (categoryName && itemsRaw.length) {
            const items = itemsRaw.map(merchantStoreNormalizeItem).filter(Boolean);
            return { name: categoryName, items: items };
          }

          if (keys.length === 1 && Array.isArray(rawCategory[keys[0]])) {
            return {
              name: merchantStoreScalar(keys[0]),
              items: rawCategory[keys[0]].map(merchantStoreNormalizeItem).filter(Boolean)
            };
          }

          return null;
        }

        function merchantStoreSanitizeYamlForParser(text) {
          return String(text || '').split('\n').map(function (line) {
            const kvMatch = line.match(/^(\s*(?:-\s*)?[^:#\n][^:]*:\s*)(.*)$/);
            if (!kvMatch) return line;
            const keyPart = kvMatch[1];
            const rawValue = kvMatch[2];
            const value = rawValue.trim();
            if (!value) return line;
            if (/^['"]/.test(value)) return line;
            if (/^[>|]/.test(value)) return line;
            if (/^\[[^\]]*\]$/.test(value)) return line;
            if (/^\{[^{}]*\}$/.test(value)) return line;
            if (/^\[.*\]\s+\S/.test(value) || /^\{.*\}\s+\S/.test(value)) {
              const escaped = value.replace(/\\/g, '\\\\').replace(/"/g, '\\"');
              return `${keyPart}"${escaped}"`;
            }
            return line;
          }).join('\n');
        }

        function merchantStoreNormalizeRawText(raw) {
          let text = String(raw || '');
          if (!text) return '';

          text = text.replace(/\r\n?/g, '\n');
          text = decodeHtmlEntities(text);
          text = text.replace(/&nbsp;/gi, ' ');
          text = text.replace(/<br\s*\/?>/gi, '\n');
          text = text.replace(/<\/?(?:div|p|ul|ol|li|section|article|blockquote|pre|code)[^>]*>/gi, '\n');
          text = text.replace(/<!--[\s\S]*?-->/g, '');

          if (text.indexOf('<') !== -1 || text.indexOf('>') !== -1) {
            const temp = document.createElement('div');
            temp.innerHTML = text;
            text = temp.textContent || temp.innerText || text;
          }

          text = text.replace(/\u00a0/g, ' ');
          text = text.replace(/^\uFEFF/, '');
          text = text.split('\n').map(function (line) {
            return line.replace(/\s+$/g, '');
          }).join('\n');
          text = text.replace(/\n{3,}/g, '\n\n');
          return text.trim();
        }

        function parseMerchantStoreYaml(raw) {
          const cleaned = merchantStoreNormalizeRawText(raw)
            .replace(/^\s*```(?:yaml|yml)?\s*/i, '')
            .replace(/\s*```\s*$/i, '')
            .trim();
          if (!cleaned) return null;
          if (typeof jsyaml === 'undefined' || typeof jsyaml.load !== 'function') return null;

          let parsed;
          try {
            parsed = jsyaml.load(cleaned);
          } catch (e) {
            try {
              parsed = jsyaml.load(merchantStoreSanitizeYamlForParser(cleaned));
            } catch (e2) {
              return null;
            }
          }

          if (!parsed || typeof parsed !== 'object') return null;

          const meta = {
            storeName: merchantStoreScalar(parsed.store_name || parsed['商店名'] || parsed['店名'])
          };
          const categories = [];

          const categoryList = parsed.categories || parsed['分类'];
          if (Array.isArray(categoryList)) {
            categoryList.forEach(function (entry) {
              const normalized = merchantStoreNormalizeCategoryObject(entry);
              if (normalized) categories.push(normalized);
            });
          } else {
            const META_KEYS = new Set(['schema', 'schema_version', 'version', 'store_name', '商店名', '店名', 'categories', '分类']);
            Object.keys(parsed).forEach(function (key) {
              if (META_KEYS.has(key)) return;
              const value = parsed[key];
              if (Array.isArray(value)) {
                categories.push({
                  name: merchantStoreScalar(key),
                  items: value.map(merchantStoreNormalizeItem).filter(Boolean)
                });
                return;
              }
              if (value && typeof value === 'object') {
                const normalized = merchantStoreNormalizeCategoryObject(Object.assign({ 分类: key }, value));
                if (normalized) categories.push(normalized);
              }
            });
          }

          return categories.length ? { meta: meta, categories: categories } : null;
        }

        function parseMerchantStoreLegacy(raw) {
          const lines = merchantStoreNormalizeRawText(raw).split('\n');
          const categories = [];
          const meta = {};
          const KNOWN_PROP_KEYS = new Set(['源世界', '名称', '类型', '部位', '品质', '标签', '等级', '售价', '数量', '属性加成', '效果', '描述']);
          const LIST_CHILD_KEYS = new Set(['标签']);
          const MAP_CHILD_KEYS = new Set(['属性加成']);
          const META_KEYS = new Set(['store_name', '商店名', '店名']);
          const CATEGORY_KEYS = new Set(['分类', 'category', 'name', '分类名']);
          const CATEGORY_CONTAINER_KEYS = new Set(['categories', '分类']);
          const ITEM_CONTAINER_KEYS = new Set(['items', '商品', '条目']);
          let currentCategoryListIndent = -1;
          let currentCategory = null;
          let currentCategoryIndent = -1;
          let currentItem = null;
          let currentItemIndent = -1;
          let currentItemListIndent = -1;
          let lastPropKey = null;
          let lastPropIndent = -1;

          function appendPropValue(props, key, value) {
            const text = merchantStoreScalar(value);
            if (!text) return;
            if (key === '标签') {
              const prevList = Array.isArray(props[key]) ? props[key] : merchantStoreNormalizeTags(props[key]);
              props[key] = prevList.concat(text).filter(Boolean);
              return;
            }
            if (key === '属性加成') {
              const prev = merchantStoreScalar(props[key]);
              props[key] = prev ? `${prev}, ${text}` : text;
              return;
            }
            const prev = merchantStoreScalar(props[key]);
            props[key] = prev ? `${prev}, ${text}` : text;
          }

          function assignKnownProp(props, key, value) {
            if (!KNOWN_PROP_KEYS.has(key)) return false;
            const cleaned = merchantStoreScalar(String(value || '').replace(/^["'\s]+|["'\s]+$/g, ''));
            if (key === '品质') {
              props[key] = merchantStoreNormalizeQuality(cleaned);
              return true;
            }
            if (key === '标签') {
              props[key] = cleaned ? merchantStoreNormalizeTags(cleaned) : [];
              return true;
            }
            if (key === '属性加成') {
              props[key] = merchantStoreNormalizeAttributes(cleaned);
              return true;
            }
            props[key] = cleaned;
            return true;
          }

          function parseInlineProps(inlineRaw, props) {
            const body = inlineRaw.replace(/^\{\s*|\s*\}$/g, '');
            if (!body) return;
            const parts = body.split(/,(?![^\[]*\])(?![^\{]*\})/);
            parts.forEach(function (part) {
              const idx = part.indexOf(':');
              if (idx === -1) return;
              const key = part.substring(0, idx).trim();
              const val = part.substring(idx + 1);
              if (!key) return;
              assignKnownProp(props, key, val);
            });
          }

          function beginCategory(name, indent) {
            const categoryName = merchantStoreScalar(String(name || '').replace(/^["'\s]+|["'\s]+$/g, ''));
            if (!categoryName) return false;
            currentCategory = { name: categoryName, items: [] };
            categories.push(currentCategory);
            currentCategoryIndent = indent;
            currentItem = null;
            currentItemIndent = -1;
            currentItemListIndent = -1;
            lastPropKey = null;
            lastPropIndent = -1;
            return true;
          }

          function beginItem(name, indent) {
            const itemName = merchantStoreScalar(name);
            currentItem = { name: itemName, props: { 名称: itemName, 标签: [], 属性加成: {} } };
            currentCategory.items.push(currentItem);
            currentItemIndent = indent;
            lastPropKey = null;
            lastPropIndent = -1;
          }

          for (let i = 0; i < lines.length; i++) {
            const line = lines[i];
            if (!line.trim()) continue;

            const trimmed = line.trim();
            const indent = line.search(/\S/);
            if (indent < 0) continue;
            if (trimmed.startsWith('#')) continue;

            if (!trimmed.startsWith('-') && trimmed.includes(':')) {
              const topKeyIdx = trimmed.indexOf(':');
              const topKey = trimmed.substring(0, topKeyIdx).trim();
              const topVal = trimmed.substring(topKeyIdx + 1);

              if (indent === 0 && META_KEYS.has(topKey)) {
                const text = merchantStoreScalar(String(topVal || '').replace(/^["'\s]+|["'\s]+$/g, ''));
                if (text) meta.storeName = text;
                continue;
              }

              if (!topVal.trim() && CATEGORY_CONTAINER_KEYS.has(topKey)) {
                currentCategoryListIndent = indent;
                currentItem = null;
                currentItemIndent = -1;
                currentItemListIndent = -1;
                lastPropKey = null;
                lastPropIndent = -1;
                continue;
              }

              if (currentCategory && !topVal.trim() && ITEM_CONTAINER_KEYS.has(topKey) && indent > currentCategoryIndent) {
                currentItem = null;
                currentItemIndent = -1;
                currentItemListIndent = indent;
                lastPropKey = null;
                lastPropIndent = -1;
                continue;
              }
            }

            const categoryEntryMatch = line.match(/^\s*-\s*([^:]+?)\s*:\s*(.*)$/);
            if (categoryEntryMatch) {
              const entryKey = categoryEntryMatch[1].trim();
              const entryVal = categoryEntryMatch[2].trim();
              const isCategoryLevel = currentCategoryListIndent >= 0 && indent > currentCategoryListIndent && (currentItemListIndent < 0 || indent <= currentItemListIndent);
              if (CATEGORY_KEYS.has(entryKey) && isCategoryLevel) {
                if (beginCategory(entryVal, indent)) continue;
              }
            }

            if (!trimmed.startsWith('-') && /:\s*$/.test(trimmed) && (currentItem === null || indent <= currentCategoryIndent)) {
              const categoryName = trimmed.replace(/:\s*$/, '').replace(/\[|\]/g, '').trim();
              if (CATEGORY_CONTAINER_KEYS.has(categoryName) || ITEM_CONTAINER_KEYS.has(categoryName)) continue;
              beginCategory(categoryName, indent);
              continue;
            }

            if (!currentCategory) continue;

            const itemStartMatch = line.match(/^\s*-\s*(.+?)\s*:\s*(.*)$/);
            if (itemStartMatch && indent > currentCategoryIndent) {
              const itemName = itemStartMatch[1].trim();
              const rest = itemStartMatch[2].trim();
              beginItem('', indent);

              if (KNOWN_PROP_KEYS.has(itemName)) {
                assignKnownProp(currentItem.props, itemName, rest);
                if (itemName === '名称' && currentItem.props[itemName]) currentItem.name = currentItem.props[itemName];
              } else {
                currentItem.name = itemName;
                currentItem.props['名称'] = itemName;

                if (rest.startsWith('{') && rest.endsWith('}')) {
                  parseInlineProps(rest, currentItem.props);
                  if (currentItem.props['名称']) currentItem.name = currentItem.props['名称'];
                }
              }
              continue;
            }

            if (!currentItem) continue;

            if (lastPropKey !== null && indent > lastPropIndent) {
              if (trimmed.startsWith('-') && LIST_CHILD_KEYS.has(lastPropKey)) {
                const listVal = trimmed.replace(/^-+\s*/, '').trim();
                appendPropValue(currentItem.props, lastPropKey, listVal);
                continue;
              }

              if (trimmed.includes(':') && MAP_CHILD_KEYS.has(lastPropKey)) {
                const subIdx = trimmed.indexOf(':');
                const subKey = trimmed.substring(0, subIdx).trim();
                const subVal = trimmed.substring(subIdx + 1).trim();
                if (subKey) appendPropValue(currentItem.props, lastPropKey, subVal ? `${subKey}: ${subVal}` : subKey);
                continue;
              }
            }

            if (indent > currentItemIndent && !trimmed.startsWith('-') && trimmed.includes(':')) {
              const keyIdx = trimmed.indexOf(':');
              const key = trimmed.substring(0, keyIdx).trim();
              const val = trimmed.substring(keyIdx + 1);
              if (!key) continue;
              if (!assignKnownProp(currentItem.props, key, val)) continue;
              lastPropKey = key;
              lastPropIndent = indent;
              if (key === '名称' && currentItem.props[key]) currentItem.name = currentItem.props[key];
            }
          }

          return { meta: meta, categories: categories };
        }

        function parseMerchantStore(raw) {
          return parseMerchantStoreYaml(raw) || parseMerchantStoreLegacy(raw);
        }

        function renderRpgMerchantStore(raw, idx) {
          const storeData = parseMerchantStore(raw);
          if (!storeData) {
            console.error('商店数据解析失败');
            return '';
          }
          const categories = storeData.categories || [];
          if (!categories.length) {
            console.error('商店没有分类数据');
            return '';
          }
          const storeTitle = merchantStoreScalar(storeData.meta && storeData.meta.storeName) || '典狱长的货摊';

          let tabsHtml = '';
          let pagesHtml = '';

          // 分类名称 → 图标映射
          const catIconMap = {
            '随机本界装备': 'fa-solid fa-shield-halved', '装备': 'fa-solid fa-shield-halved', '武器': 'fa-solid fa-shield-halved',
            '固定常驻物资': 'fa-solid fa-box-open', '常驻': 'fa-solid fa-box-open', '物资': 'fa-solid fa-box-open',
            '其他杂物': 'fa-solid fa-bag-shopping', '杂物': 'fa-solid fa-bag-shopping', '杂货': 'fa-solid fa-bag-shopping',
            '异界奇珍': 'fa-solid fa-gem', '奇珍': 'fa-solid fa-gem', '珍品': 'fa-solid fa-gem',
            '消耗品': 'fa-solid fa-flask', '药品': 'fa-solid fa-flask',
            '材料': 'fa-solid fa-cubes', '素材': 'fa-solid fa-cubes',
            '卷轴': 'fa-solid fa-scroll', '书籍': 'fa-solid fa-book',
            '饰品': 'fa-solid fa-ring', '首饰': 'fa-solid fa-ring',
            '防具': 'fa-solid fa-vest-patches', '护甲': 'fa-solid fa-vest-patches',
          };
          const getCatIcon = (name) => {
            if (catIconMap[name]) return catIconMap[name];
            for (const k of Object.keys(catIconMap)) { if (name.includes(k)) return catIconMap[k]; }
            return 'ra ra-scroll-unfurled';
          };

          // 物品类型 → 图标映射
          const typeIconMap = {
            '武器': 'ra ra-sword', '剑': 'ra ra-sword', '刀': 'ra ra-bowie-knife',
            '弓': 'ra ra-crossbow', '杖': 'ra ra-fairy-wand', '法杖': 'ra ra-fairy-wand',
            '防具': 'ra ra-shield', '护甲': 'ra ra-shield', '盾': 'ra ra-shield',
            '头盔': 'ra ra-helmet', '盔甲': 'ra ra-helmet',
            '首饰': 'ra ra-gem-pendant', '饰品': 'ra ra-gem-pendant', '戒指': 'ra ra-gem-pendant',
            '项链': 'ra ra-gem-pendant', '护符': 'ra ra-gem-pendant',
            '消耗品': 'ra ra-health', '药水': 'ra ra-health', '药膏': 'ra ra-health',
            '食物': 'ra ra-apple', '材料': 'ra ra-mining-diamonds', '素材': 'ra ra-mining-diamonds',
            '卷轴': 'ra ra-scroll-unfurled', '书籍': 'ra ra-book',
            '工具': 'ra ra-gear-hammer', '杂货': 'ra ra-bone-knife', '杂物': 'ra ra-bone-knife',
          };
          const getTypeIcon = (type) => {
            if (!type) return 'ra ra-round-bottom-flask';
            const clean = type.replace(/\[|\]/g, '').trim();
            if (typeIconMap[clean]) return typeIconMap[clean];
            for (const k of Object.keys(typeIconMap)) { if (clean.includes(k)) return typeIconMap[k]; }
            return 'ra ra-round-bottom-flask';
          };

          categories.forEach((cat, cIdx) => {
            const catIcon = getCatIcon(cat.name);
            tabsHtml += `<button class="merch-tab ${cIdx === 0 ? 'active' : ''}" onclick="switchMerch(event, '${idx}', 'cat-${cIdx}')"><i class="${catIcon}" style="margin-right:5px;font-size:12px;opacity:0.7"></i>${rpgEsc(cat.name)}</button>`;

            let itemsHtml = '';
            if (cat.items.length === 0) {
              itemsHtml = `<div class="merch-empty">该货架暂时空缺</div>`;
            } else {
              itemsHtml = `<div class="merch-items-list">` + cat.items.map(item => {
                const name = item.name;
                const price = merchantStoreScalar(item.props['售价']) || '???';
                const rawPrice = merchantParseNumber(price);
                const displayPrice = merchantFormatDisplayPrice(price);
                const quality = merchantStoreNormalizeQuality(item.props['品质'] || '普通') || '普通';
                const type = merchantStoreScalar(item.props['类型']);
                const effect = merchantStoreScalar(item.props['效果']);
                const desc = merchantStoreScalar(item.props['描述']);
                const quantity = merchantStoreScalar(item.props['数量']);
                const slot = merchantStoreScalar(item.props['部位']);
                const level = merchantStoreScalar(item.props['等级']);
                const sourceWorld = merchantStoreScalar(item.props['源世界']);
                const tagsRaw = item.props['标签'];
                const attributes = item.props['属性加成'];

                const qColorMap = { '普通': '#4b5563', '精良': '#3b82f6', '稀有': '#8b5cf6', '卓越': '#ec4899', '传说': '#f59e0b', '史诗': '#eab308', '神话': '#f43f5e' };
                const color = qColorMap[quality] || '#4b5563';

                // 标签渲染
                let tagsHtml = '';
                if (tagsRaw && tagsRaw !== '无') {
                  let cleanTags = merchantStoreFormatTags(tagsRaw);
                  tagsHtml = cleanTags.map(t => `<span class="merch-item-tag">${rpgEsc(t)}</span>`).join('');
                }

                const cleanAttr = merchantStoreFormatAttributes(attributes);

                // 构建详情行
                let detailRows = '';
                if (sourceWorld) detailRows += `<div class="merch-detail-row"><span class="merch-detail-label"><i class="ra ra-crystal-ball" style="margin-right:4px;opacity:0.6"></i>源世界</span><span class="merch-detail-value source-value">${rpgEsc(sourceWorld)}</span></div>`;
                if (slot && slot !== '无') detailRows += `<div class="merch-detail-row"><span class="merch-detail-label"><i class="ra ra-hand" style="margin-right:4px;opacity:0.6"></i>部位</span><span class="merch-detail-value">${rpgEsc(slot)}</span></div>`;
                if (level) detailRows += `<div class="merch-detail-row"><span class="merch-detail-label"><i class="ra ra-level-three" style="margin-right:4px;opacity:0.6"></i>等级</span><span class="merch-detail-value">Lv.${rpgEsc(level)}</span></div>`;
                if (cleanAttr) detailRows += `<div class="merch-detail-row"><span class="merch-detail-label"><i class="ra ra-muscle-up" style="margin-right:4px;opacity:0.6"></i>属性</span><span class="merch-detail-value attr-value">${rpgEsc(cleanAttr)}</span></div>`;
                if (effect && effect !== '无') detailRows += `<div class="merch-detail-row"><span class="merch-detail-label"><i class="ra ra-burning-embers" style="margin-right:4px;opacity:0.6"></i>效果</span><span class="merch-detail-value effect-value">${rpgEsc(effect)}</span></div>`;
                if (desc && desc !== '无') detailRows += `<div class="merch-detail-row"><span class="merch-detail-label"><i class="ra ra-scroll-unfurled" style="margin-right:4px;opacity:0.6"></i>描述</span><span class="merch-detail-value desc-value">${rpgEsc(desc)}</span></div>`;
                if (tagsHtml) detailRows += `<div class="merch-detail-row"><span class="merch-detail-label"><i class="ra ra-wooden-sign" style="margin-right:4px;opacity:0.6"></i>标签</span><span class="merch-detail-value"><span class="merch-detail-tags">${tagsHtml}</span></span></div>`;

                const hasDetails = detailRows.length > 0;

                return `<div class="merch-item">
                  <div class="merch-item-summary" onclick="toggleMerchItem(this)">
                    <div class="merch-item-info">
                      <div class="merch-item-name" style="color:${color}" title="${escapeHtmlAttr(name)}">${rpgEsc(name)}${quantity && quantity !== '1' ? ` <span style="color:var(--text-muted);font-size:12px">x${rpgEsc(quantity)}</span>` : ''}</div>
                      <div class="merch-item-meta">
                        <span class="merch-item-badge" style="background:${color}15;color:${color}">${rpgEsc(quality)}</span>
                        ${type ? `<span class="merch-item-type">${rpgEsc(type.replace(/\[|\]/g, ''))}</span>` : ''}
                      </div>
                    </div>
                    <div class="merch-item-price" data-merch-price="${escapeHtmlAttr(String(rawPrice))}"><span>${rpgEsc(displayPrice)}</span><i class="fa-solid fa-coins"></i></div>
                    ${hasDetails ? '<i class="fa-solid fa-chevron-down merch-item-chevron"></i>' : ''}
                  </div>
                  ${hasDetails ? `<div class="merch-item-details"><div class="merch-item-details-inner">${detailRows}<button class="merch-buy-btn"><i class="ra ra-gold-bar" style="margin-right:6px;font-size:13px"></i>购 入</button></div></div>` : `<div style="padding:0 14px 8px"><button class="merch-buy-btn"><i class="ra ra-gold-bar" style="margin-right:6px;font-size:13px"></i>购 入</button></div>`}
                </div>`;
              }).join('') + `</div>`;
            }

            pagesHtml += `<div id="merch-${idx}-cat-${cIdx}" class="merch-page ${cIdx === 0 ? 'active' : ''}">${itemsHtml}</div>`;
          });

          tabsHtml += `<button class="merch-tab tab-sell" onclick="switchMerch(event, '${idx}', 'sell')"><i class="fa-solid fa-scale-balanced mr-1"></i>出售物资</button>`;
          pagesHtml += `
            <div id="merch-${idx}-sell" class="merch-page">
                <div class="merch-sell-container">
                   <div class="merch-sell-icon"><i class="ra ra-knapsack"></i></div>
                   <p class="merch-sell-text">请在下方选择需要估价的物资或装备...</p>
                </div>
            </div>
          `;

          return `
          <div class="log-card card-merchant card-animate" style="animation-delay:${idx * 0.08}s">
            <div class="merch-header">
              <div class="merch-title-area">
                <span class="merch-title-line"></span>
                <i class="ra ra-shop merch-title-icon"></i>
                <span class="merch-title-text">${rpgEsc(storeTitle)}</span>
                <i class="ra ra-shop merch-title-icon" style="transform:scaleX(-1)"></i>
                <span class="merch-title-line"></span>
              </div>
              <div class="merch-tabs-container">
                ${tabsHtml}
              </div>
            </div>
            <div class="merch-body">
              ${pagesHtml}
            </div>
          </div>
          `;
        }

        // 全局切换页签方法
        window.switchMerch = function (e, idx, pageId) {
          const card = document.getElementById(`merch-${idx}-${pageId}`).closest('.card-merchant');
          card.querySelectorAll('.merch-tab').forEach(t => t.classList.remove('active'));
          card.querySelectorAll('.merch-page').forEach(p => p.classList.remove('active'));
          e.currentTarget.classList.add('active');
          document.getElementById(`merch-${idx}-${pageId}`).classList.add('active');
          if (String(pageId) === 'sell') {
            const state = merchantEnsureState(idx);
            if (!state.sellRendered || state.sellDirty) merchantRenderSellListByCard(card, idx);
          }
        }

        // 商品详情展开/收起（使用精确 scrollHeight 替代固定 max-height）
        window.toggleMerchItem = function (summaryEl) {
          const item = summaryEl.closest('.merch-item');
          const details = item.querySelector('.merch-item-details');
          if (!details) { item.classList.toggle('expanded'); return; }
          const isExpanded = item.classList.contains('expanded');
          if (isExpanded) {
            // 收起：先锁定当前高度，再过渡到0
            details.style.maxHeight = details.scrollHeight + 'px';
            requestAnimationFrame(() => {
              details.style.maxHeight = '0';
            });
            item.classList.remove('expanded');
          } else {
            // 展开：先确保从0开始，再设置精确目标高度
            details.style.maxHeight = '0';
            item.classList.add('expanded');
            requestAnimationFrame(() => {
              details.style.maxHeight = details.scrollHeight + 'px';
            });
            // 过渡结束后清理监听；保持数值高度可让后续收起过渡稳定
            const onEnd = () => {
              details.removeEventListener('transitionend', onEnd);
            };
            details.addEventListener('transitionend', onEnd);
          }
        }

        const merchantTradeState = {};
        let merchantTradeBound = false;

        function merchantDetectCardIdx(card, fallbackIdx) {
          const sellPage = card.querySelector('.merch-page[id$="-sell"]');
          if (sellPage && sellPage.id) {
            const m = sellPage.id.match(/^merch-(.+)-sell$/);
            if (m && m[1] !== undefined) return String(m[1]);
          }
          return String(fallbackIdx);
        }

        function merchantEnsureState(idx) {
          const k = String(idx);
          if (!merchantTradeState[k]) {
            merchantTradeState[k] = { buys: {}, sells: {}, stock: {}, uiCollapsed: true, sellTab: 'weapon', sellRendered: false, sellDirty: true };
          } else if (typeof merchantTradeState[k].uiCollapsed !== 'boolean') {
            merchantTradeState[k].uiCollapsed = true;
          }
          if (typeof merchantTradeState[k].sellTab !== 'string' || merchantTradeState[k].sellTab.trim() === '') {
            merchantTradeState[k].sellTab = 'weapon';
          }
          if (typeof merchantTradeState[k].sellRendered !== 'boolean') merchantTradeState[k].sellRendered = false;
          if (typeof merchantTradeState[k].sellDirty !== 'boolean') merchantTradeState[k].sellDirty = true;
          return merchantTradeState[k];
        }

        function merchantIsSellPageActive(card, idx) {
          const sellPage = card.querySelector('#merch-' + idx + '-sell');
          return !!(sellPage && sellPage.classList.contains('active'));
        }

        function merchantGetEquipName(equip, fallbackIndex) {
          if (!equip || typeof equip !== 'object') return '装备' + String(fallbackIndex + 1);
          const candidates = ['名称', '名字', 'name', '装备名', '物品名'];
          for (let i = 0; i < candidates.length; i++) {
            const key = candidates[i];
            if (equip[key] !== undefined && equip[key] !== null && String(equip[key]).trim() !== '') {
              return String(equip[key]).trim();
            }
          }
          return '装备' + String(fallbackIndex + 1);
        }

        function merchantGetSellCategory(item) {
          if (!item || typeof item !== 'object') return 'hidden';
          if (item.__sellKind === '道具') {
            const t = String(item.类型 || '').trim();
            if (t.includes('消耗')) return 'item_consume';
            if (t.includes('材料')) return 'item_material';
            if (t.includes('杂')) return 'item_misc';
            return 'hidden';
          }
          const t = String(item.类型 || '').replace(/\[|\]/g, '').trim();
          if (t.includes('武器')) return 'weapon';
          if (t.includes('防具')) return 'armor';
          if (t.includes('首饰')) return 'accessory';
          return 'hidden';
        }

        function merchantExtractBuyName(itemEl) {
          const nameEl = itemEl ? itemEl.querySelector('.merch-item-name') : null;
          if (!nameEl) return '';
          const clone = nameEl.cloneNode(true);
          clone.querySelectorAll('span').forEach(function (el) { el.remove(); });
          return clone.textContent.trim();
        }

        function merchantExtractBuyPrice(itemEl) {
          const priceEl = itemEl ? itemEl.querySelector('.merch-item-price') : null;
          if (!priceEl) return 0;
          const rawPrice = priceEl.getAttribute('data-merch-price');
          if (rawPrice !== null && rawPrice !== '') return merchantParseNumber(rawPrice);
          return merchantParseNumber(priceEl.textContent);
        }

        function merchantExtractBuyTotalQty(itemEl) {
          if (!itemEl) return 1;
          const cached = parseInt(itemEl.getAttribute('data-merch-total-qty') || '', 10);
          if (Number.isFinite(cached) && cached > 0) return cached;
          const nameEl = itemEl.querySelector('.merch-item-name');
          const txt = nameEl ? (nameEl.textContent || '') : '';
          const m = txt.match(/x\s*(\d+)\s*$/i);
          const qty = m ? parseInt(m[1], 10) : 1;
          const safe = Number.isFinite(qty) && qty > 0 ? qty : 1;
          itemEl.setAttribute('data-merch-total-qty', String(safe));
          return safe;
        }

        function merchantSetupItemStocks(card, idx) {
          const state = merchantEnsureState(idx);
          const items = Array.from(card.querySelectorAll('.merch-item')).filter(function (itemEl) {
            return !!itemEl.querySelector('.merch-buy-btn');
          });
          items.forEach(function (itemEl, i) {
            let key = itemEl.getAttribute('data-merch-item-key');
            if (!key) {
              key = 'merch_' + String(idx) + '_' + String(i);
              itemEl.setAttribute('data-merch-item-key', key);
            }
            const totalQty = merchantExtractBuyTotalQty(itemEl);
            const name = merchantExtractBuyName(itemEl);
            const price = merchantExtractBuyPrice(itemEl);
            if (!state.stock[key]) {
              state.stock[key] = { key: key, name: name, price: price, total: totalQty, remaining: totalQty };
            } else {
              state.stock[key].name = name || state.stock[key].name;
              if (price > 0) state.stock[key].price = price;
              if (!Number.isFinite(state.stock[key].total) || state.stock[key].total <= 0) state.stock[key].total = totalQty;
              if (!Number.isFinite(state.stock[key].remaining)) state.stock[key].remaining = state.stock[key].total;
              if (state.stock[key].remaining > state.stock[key].total) state.stock[key].remaining = state.stock[key].total;
            }
          });
        }

        function merchantSyncStockUi(card, idx) {
          const state = merchantEnsureState(idx);
          merchantSetupItemStocks(card, idx);
          Object.keys(state.stock).forEach(function (key) {
            const st = state.stock[key];
            if (!st) return;
            const itemEl = card.querySelector('.merch-item[data-merch-item-key="' + key + '"]');
            if (!itemEl) return;

            const nameEl = itemEl.querySelector('.merch-item-name');
            let qtySpan = nameEl ? nameEl.querySelector('[data-stock-remain="1"]') : null;
            if (nameEl) {
              const allSpans = Array.from(nameEl.querySelectorAll('span'));
              if (!qtySpan && allSpans.length > 0) {
                qtySpan = allSpans[0];
                qtySpan.setAttribute('data-stock-remain', '1');
              }
              if (!qtySpan) {
                qtySpan = document.createElement('span');
                qtySpan.setAttribute('data-stock-remain', '1');
                qtySpan.style.color = 'var(--text-muted)';
                qtySpan.style.fontSize = '12px';
                qtySpan.style.marginLeft = '6px';
                nameEl.appendChild(qtySpan);
              }
              allSpans.forEach(function (sp) {
                if (sp !== qtySpan) sp.remove();
              });
            }
            if (qtySpan) {
              qtySpan.textContent = st.total > 1 ? ('x' + String(st.remaining)) : (st.remaining > 0 ? '' : '售罄');
            }

            const buyBtns = itemEl.querySelectorAll('.merch-buy-btn');
            buyBtns.forEach(function (btn) {
              if (!btn.dataset.originHtml) btn.dataset.originHtml = btn.innerHTML;
              if (st.remaining <= 0) {
                btn.disabled = true;
                btn.style.opacity = '0.55';
                btn.style.cursor = 'not-allowed';
                btn.innerHTML = '<i class="ra ra-cancel" style="margin-right:6px;font-size:13px"></i>售 罄';
              } else {
                btn.disabled = false;
                btn.style.opacity = '';
                btn.style.cursor = '';
                btn.innerHTML = btn.dataset.originHtml;
              }
            });
          });
        }

        function merchantGetBuyList(idx) {
          const state = merchantEnsureState(idx);
          return Object.keys(state.buys).map(function (k) { return state.buys[k]; }).filter(function (v) { return v && v.qty > 0; });
        }

        function merchantGetSellList(idx) {
          const state = merchantEnsureState(idx);
          return Object.keys(state.sells).map(function (k) { return state.sells[k]; }).filter(function (v) { return v && (v.qty || 0) > 0; });
        }

        function merchantGetBuyTotal(idx) {
          const buys = merchantGetBuyList(idx);
          let sum = 0;
          for (let i = 0; i < buys.length; i++) {
            sum += (buys[i].price || 0) * (buys[i].qty || 0);
          }
          return sum;
        }

        function merchantAddBuyItem(state, key, name, price, delta) {
          if (!key || !name) return false;
          const step = Number(delta || 0);
          if (!step) return false;
          const stock = state.stock[key];
          if (!stock) return false;

          if (!state.buys[key]) state.buys[key] = { key: key, name: name, price: price || stock.price || 0, qty: 0 };
          const entry = state.buys[key];

          if (step > 0) {
            if (stock.remaining < step) return false;
            entry.qty += step;
            stock.remaining -= step;
            if (price > 0) entry.price = price;
          } else {
            const back = Math.min(entry.qty, Math.abs(step));
            if (back <= 0) return false;
            entry.qty -= back;
            stock.remaining = Math.min(stock.total, stock.remaining + back);
          }

          if (entry.qty <= 0) delete state.buys[key];
          return true;
        }

        function merchantAddSellItem(state, key, name, delta, maxQty) {
          if (!key || !name) return false;
          const step = Number(delta || 0);
          const limit = Math.max(1, merchantParseNumber(maxQty || 1));
          if (!step) return false;

          if (!state.sells[key]) state.sells[key] = { key: key, name: name, qty: 0, max: limit };
          const entry = state.sells[key];
          entry.max = Math.max(merchantParseNumber(entry.max || 0), limit);

          if (step > 0) {
            if ((entry.qty || 0) >= entry.max) return false;
            entry.qty = Math.min(entry.max, (entry.qty || 0) + step);
          } else {
            const back = Math.min(entry.qty || 0, Math.abs(step));
            if (back <= 0) return false;
            entry.qty = (entry.qty || 0) - back;
          }

          if ((entry.qty || 0) <= 0) delete state.sells[key];
          return true;
        }

        function merchantCreateTagBtn(cls, text, action, idx, attrs) {
          const btn = document.createElement('button');
          btn.className = cls;
          btn.setAttribute('type', 'button');
          btn.setAttribute('data-merchant-action', action);
          btn.setAttribute('data-merch-idx', String(idx));
          btn.textContent = text;
          if (attrs && typeof attrs === 'object') {
            Object.keys(attrs).forEach(function (k) {
              btn.setAttribute(k, attrs[k]);
            });
          }
          return btn;
        }

        function merchantComposeCheckoutText(idx) {
          const buys = merchantGetBuyList(idx);
          const sells = merchantGetSellList(idx);
          if (buys.length === 0 && sells.length === 0) return '';
          const buyText = buys.length > 0 ? buys.map(function (it) { return it.name + 'x' + it.qty; }).join('+') : '无';
          const sellText = sells.length > 0 ? sells.map(function (it) { return it.name + 'x' + (it.qty || 1); }).join('+') : '无';
          const total = merchantGetBuyTotal(idx);
          return '买入' + buyText + '，共计花费' + String(total) + '通用币。并卖出' + sellText + '。请对卖出物品估价。';
        }

        function merchantRenderSellListByCard(card, idx) {
          const sellPage = card.querySelector('#merch-' + idx + '-sell');
          if (!sellPage) return;
          const container = sellPage.querySelector('.merch-sell-container');
          if (!container) return;
          const state = merchantEnsureState(idx);
          state.sellRendered = true;
          state.sellDirty = false;
          const equips = merchantGetSellableEquipments().filter(function (it) { return merchantGetSellCategory(it) !== 'hidden'; });
          const sellList = merchantGetSellList(idx);
          const selectedCount = sellList.length;
          const selectedUnits = sellList.reduce(function (sum, it) { return sum + (it.qty || 0); }, 0);

          const hint = container.querySelector('.merch-sell-text');
          if (hint) {
            hint.textContent = equips.length > 0
              ? ('请选择要卖出的物资。已加入 ' + String(selectedCount) + ' 项（共 ' + String(selectedUnits) + ' 件），稍后在下方结算预览统一发送。')
              : '暂无可出售物资。';
          }

          let listHost = container.querySelector('.merchant-sell-list-runtime');
          if (!listHost) {
            listHost = document.createElement('div');
            listHost.className = 'merchant-sell-list-runtime';
            listHost.style.margin = '6px 0 12px';
            container.appendChild(listHost);
          }
          while (listHost.firstChild) listHost.removeChild(listHost.firstChild);

          if (equips.length > 0) {
            const tabDefs = [
              { key: 'weapon', label: '武器', icon: 'ra ra-sword' },
              { key: 'armor', label: '防具', icon: 'ra ra-shield' },
              { key: 'accessory', label: '首饰', icon: 'ra ra-gem-pendant' },
              { key: 'item_consume', label: '消耗品', icon: 'ra ra-health' },
              { key: 'item_material', label: '材料', icon: 'ra ra-mining-diamonds' },
              { key: 'item_misc', label: '杂物', icon: 'ra ra-bone-knife' }
            ];
            const availableTabs = tabDefs;
            const defaultTab = availableTabs.length > 0 ? availableTabs[0].key : tabDefs[0].key;
            if (!state.sellTab || !availableTabs.some(function (t) { return t.key === state.sellTab; })) state.sellTab = defaultTab;

            const tabsEl = document.createElement('div');
            tabsEl.className = 'merchant-sell-tabs';
            availableTabs.forEach(function (tab) {
              const btn = document.createElement('button');
              btn.className = 'merchant-sell-tab' + (state.sellTab === tab.key ? ' active' : '');
              btn.setAttribute('type', 'button');
              btn.setAttribute('data-merchant-action', 'sell-tab');
              btn.setAttribute('data-merch-idx', String(idx));
              btn.setAttribute('data-sell-tab', tab.key);
              btn.innerHTML = '<i class="' + tab.icon + '" style="font-size:11px;opacity:0.75"></i>' + tab.label;
