        function merchantNotify(message) {
          if (typeof showSettingsMessage === 'function') showSettingsMessage(message);
        }

        function merchantRefreshSellUi(card, idx, state) {
          if (merchantIsSellPageActive(card, idx)) merchantRenderSellListByCard(card, idx);
          else state.sellDirty = true;
        }

        function merchantResetTradeState(card, idx, state) {
          Object.keys(state.buys).forEach(function (k) {
            const entry = state.buys[k];
            if (!entry) return;
            merchantAddBuyItem(state, entry.key, entry.name, entry.price || 0, -(entry.qty || 0));
          });
          state.buys = {};
          state.sells = {};
          merchantRefreshSellUi(card, idx, state);
          merchantRenderCartByCard(card, idx);
        }

        function merchantHandleBuyAction(action, actionEl, card, idx, state) {
          if (action === 'buy') {
            const itemEl = actionEl.closest('.merch-item');
            const buyKey = itemEl ? (itemEl.getAttribute('data-merch-item-key') || '') : '';
            const name = merchantExtractBuyName(itemEl);
            const price = merchantExtractBuyPrice(itemEl);
            if (!buyKey || !name) return true;
            const ok = merchantAddBuyItem(state, buyKey, name, price, 1);
            if (!ok) {
              merchantNotify('库存不足或已售罄');
              merchantSyncStockUi(card, idx);
              return true;
            }
            merchantRenderCartByCard(card, idx);
            return true;
          }

          if (action !== 'buy-inc' && action !== 'buy-dec' && action !== 'buy-remove') return false;

          const buyKey = actionEl.getAttribute('data-buy-key') || '';
          const name = actionEl.getAttribute('data-buy-name') || '';
          if (!buyKey || !name) return true;

          if (action === 'buy-inc') {
            const price = merchantParseNumber(actionEl.getAttribute('data-buy-price') || '0');
            const ok = merchantAddBuyItem(state, buyKey, name, price, 1);
            if (!ok) merchantNotify('库存不足或已售罄');
          } else if (action === 'buy-dec') {
            if (!state.buys[buyKey]) return true;
            merchantAddBuyItem(state, buyKey, name, state.buys[buyKey].price || 0, -1);
          } else if (state.buys[buyKey]) {
            const qty = state.buys[buyKey].qty || 0;
            if (qty > 0) merchantAddBuyItem(state, buyKey, name, state.buys[buyKey].price || 0, -qty);
          }

          merchantRenderCartByCard(card, idx);
          return true;
        }

        function merchantHandleSellAction(action, actionEl, card, idx, state) {
          if (action === 'sell-tab') {
            state.sellTab = actionEl.getAttribute('data-sell-tab') || 'weapon';
            merchantRenderSellListByCard(card, idx);
            return true;
          }

          const isSellMutation = action === 'sell-add' || action === 'toggle-sell' || action === 'sell-inc' || action === 'sell-dec' || action === 'sell-remove';
          if (!isSellMutation) return false;

          const key = actionEl.getAttribute('data-sell-key') || '';
          const name = actionEl.getAttribute('data-sell-name') || key || '未命名物资';
          if (!key || !name) return true;

          let delta = 0;
          let maxQty = 1;
          const forceFullRender = action === 'sell-add' || action === 'toggle-sell';

          if (action === 'sell-add' || action === 'sell-inc') {
            delta = 1;
            maxQty = merchantParseNumber(actionEl.getAttribute('data-sell-max') || '1');
          } else if (action === 'toggle-sell') {
            delta = 1;
            maxQty = state.sells[key] ? (state.sells[key].max || 1) : 1;
          } else if (action === 'sell-dec') {
            if (!state.sells[key]) return true;
            delta = -1;
            maxQty = state.sells[key].max || 1;
          } else {
            if (!state.sells[key]) return true;
            delta = -(state.sells[key].qty || 0);
            maxQty = state.sells[key].max || 1;
          }

          const ok = merchantAddSellItem(state, key, name, delta, maxQty);
          if (!ok && delta > 0) merchantNotify('库存不足或已售罄');

          if (forceFullRender) merchantRenderSellListByCard(card, idx);
          else merchantRefreshSellUi(card, idx, state);
          merchantRenderCartByCard(card, idx);
          return true;
        }

        function initMerchantTradeUi() {
          const cards = Array.from(document.querySelectorAll('.card-merchant'));
          if (cards.length === 0) return;
          for (let i = 0; i < cards.length; i++) {
            const card = cards[i];
            const idx = merchantDetectCardIdx(card, i);
            card.setAttribute('data-merch-idx', idx);
            merchantSetupItemStocks(card, idx);
            const buyBtns = card.querySelectorAll('.merch-buy-btn');
            buyBtns.forEach(function (btn) {
              btn.setAttribute('type', 'button');
              btn.setAttribute('data-merchant-action', 'buy');
              btn.setAttribute('data-merch-idx', idx);
            });
            merchantSyncStockUi(card, idx);
            merchantRenderCartByCard(card, idx);
          }

          if (!merchantTradeBound) {
            document.addEventListener('click', function (ev) {
              const actionEl = ev.target.closest('[data-merchant-action]');
              if (!actionEl) return;
              const action = actionEl.getAttribute('data-merchant-action');
              const card = actionEl.closest('.card-merchant');
              if (!card) return;
              const idx = actionEl.getAttribute('data-merch-idx') || card.getAttribute('data-merch-idx') || '0';
              const state = merchantEnsureState(idx);

              if (action === 'toggle-cart') {
                ev.preventDefault();
                state.uiCollapsed = !state.uiCollapsed;
                merchantRenderCartByCard(card, idx);
                return;
              }

              if (action === 'buy' || action === 'buy-inc' || action === 'buy-dec' || action === 'buy-remove') {
                ev.preventDefault();
                ev.stopPropagation();
                merchantHandleBuyAction(action, actionEl, card, idx, state);
                return;
              }

              if (action === 'sell-tab' || action === 'sell-add' || action === 'toggle-sell' || action === 'sell-inc' || action === 'sell-dec' || action === 'sell-remove') {
                ev.preventDefault();
                merchantHandleSellAction(action, actionEl, card, idx, state);
                return;
              }

              if (action === 'clear-cart') {
                ev.preventDefault();
                merchantResetTradeState(card, idx, state);
                return;
              }

              if (action === 'checkout') {
                ev.preventDefault();
                const text = merchantComposeCheckoutText(idx);
                if (!text) {
                  merchantNotify('请先选择买入或卖出项');
                  return;
                }
                const ok = merchantSendMessageToChat(text);
                if (!ok) {
                  merchantNotify('发送失败：未找到聊天输入框');
                  return;
                }
                merchantResetTradeState(card, idx, state);
                merchantNotify('已发送结算语句');
              }
            });
            merchantTradeBound = true;
          }
        }

        // ===== COMBAT SNAPSHOT (战斗快照) RENDERER =====
        const CSX_FIELDS = ['战斗轮次', '轮次', '行动轴', '敌方单位', '我方状态/资源', '我方状态', '我方资源', '我方', '队伍协作', '距离变化', '本轮已行动', '已行动', '本轮未行动', '未行动'];
        const CSX_WARM = [26, 40, 300, 332];
        const CSX_COOL = [198, 216, 236, 260, 286];
        function csxHash(s) { let h = 0; s = String(s); for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0; return h >>> 0; }
        function csxPalette(name) {
          const h = csxHash(name), size = 2 + (h % 3), warmFirst = (h & 1) === 0;
          const wOff = (h >> 1) % CSX_WARM.length, cOff = (h >> 2) % CSX_COOL.length, pal = [];
          for (let i = 0; i < size; i++) {
            const useWarm = warmFirst ? (i % 2 === 0) : (i % 2 === 1), j = Math.floor(i / 2);
            pal.push(useWarm ? CSX_WARM[(wOff + j) % CSX_WARM.length] : CSX_COOL[(cOff + j) % CSX_COOL.length]);
          }
          return pal;
        }
        function csxSplitTop(text, seps) {
          const opens = '（([', closes = '）)]', out = []; let depth = 0, cur = '';
          for (const ch of String(text)) {
            if (opens.indexOf(ch) !== -1) depth++; else if (closes.indexOf(ch) !== -1 && depth > 0) depth--;
            if (depth === 0 && seps.indexOf(ch) !== -1) { out.push(cur); cur = ''; } else cur += ch;
          }
          out.push(cur); return out.map(s => s.trim()).filter(Boolean);
        }
        function csxSplitSub(text) {
          const m = String(text).match(/^(.*?)\s*[（(]([^（）()]*)[）)]\s*$/);
          if (m && m[1].trim()) return { main: m[1].trim(), sub: m[2].trim() };
          return { main: String(text).trim(), sub: '' };
        }
        function csxChip(text, pal) {
          const o = csxSplitSub(text); const hue = pal[csxHash(o.main) % pal.length];
          return '<span class="cs-chip" style="--csh:' + hue + '">' + rpgEsc(o.main) + (o.sub ? '<span class="cs-sub">' + rpgEsc(o.sub) + '</span>' : '') + '</span>';
        }
        function csxRankOf(t) {
          t = String(t || '');
          if (/传奇|神话|史诗/.test(t)) return '传奇';
          if (/领主/.test(t)) return '领主';
          if (/首领|头目|魔王|王者|BOSS|Boss|boss/.test(t)) return '首领';
          if (/精英|精锐/.test(t)) return '精英';
          if (/杂兵|喽啰|小兵|爪牙|炮灰|普通/.test(t)) return '杂兵';
          return '';
        }
        function csxParseEnemy(line) {
          let rest = String(line).trim(), tier = '';
          const tm = rest.match(/^\[([^\]]*)\]\s*/); if (tm) { tier = tm[1].trim(); rest = rest.slice(tm[0].length); }
          const parts = csxSplitTop(rest, '|'); let name = '', hp = null, dist = '', statuses = [];
          if (parts.length) {
            const hm = parts[0].match(/[（(]\s*(\d+)\s*\/\s*(\d+)\s*[）)]/);
            if (hm) { hp = { cur: +hm[1], max: +hm[2] }; name = parts[0].slice(0, hm.index).trim(); } else name = parts[0].trim();
          }
          for (let i = 1; i < parts.length; i++) {
            const p = parts[i], bm = p.match(/^\[(.*)\]$/);
            if (bm) { csxSplitTop(bm[1], ',，、').forEach(x => statuses.push(x)); }
            else if (/\d+\s*米/.test(p)) dist = p.trim();
            else statuses.push(p.trim());
          }
          return { tier: tier, name: name, hp: hp, dist: dist, statuses: statuses };
        }
        function csxParseAlly(line) {
          const src = String(line || '').trim();
          const m = src.match(/^(.*?)\s*[—–-]\s*(.+)$/); let name = '', body = src;
          if (m && m[1].trim()) { name = m[1].trim(); body = m[2]; }
          else {
            const parts = csxSplitTop(src, '|');
            const first = (parts.shift() || '').trim();
            if (first && !/^\[.*\]$/.test(first)) return { name: first, segs: parts };
          }
          return { name: name, segs: csxSplitTop(body, '|') };
        }
        function csxParseAllies(text, lines) {
          const rawLines = (Array.isArray(lines) && lines.length ? lines : String(text || '').split(/\r?\n/))
            .map(s => String(s || '').trim())
            .filter(Boolean);
          const allies = [];
          rawLines.forEach(line => {
            const extra = line.replace(/^[|｜]\s*/, '');
            if ((/^[\[\]【】]/.test(line) || /^[|｜]/.test(line)) && allies.length) {
              allies[allies.length - 1].segs = allies[allies.length - 1].segs.concat(csxParseAlly(extra).segs);
              return;
            }
            const ally = csxParseAlly(line);
            if (!ally.name && ally.segs.length && allies.length) {
              allies[allies.length - 1].segs = allies[allies.length - 1].segs.concat(ally.segs);
              return;
            }
            allies.push(ally);
          });
          return allies.filter(a => a.name || a.segs.length);
        }
        function csxParseRoster(text) {
          const t = (text || '').trim(); if (!t || /^无$/.test(t)) return { names: [], note: '' };
          let rest = t, note = ''; const nm = rest.match(/[（(]([^（）()]*)[）)]\s*$/);
          if (nm) { note = nm[1].trim(); rest = rest.slice(0, nm.index).trim(); }
          return { names: csxSplitTop(rest, '|、,，'), note: note };
        }
        function renderRpgCombatSnapshot(raw, idx) {
          const decoded = decodeHtmlEntities(String(raw || '')).replace(/&nbsp;/gi, ' ');
          const fields = {}, fieldLines = {}, enemyLines = []; let cur = null;
          const headRe = new RegExp('^\\s*(' + CSX_FIELDS.map(f => f.replace(/[.*+?^${}()|[\]\\\/]/g, '\\$&')).join('|') + ')\\s*[:：]\\s*(.*)$');
          decoded.split('\n').forEach(rawl => {
            const line = rawl.trim(); if (!line) return;
            const m = line.match(headRe);
            if (m) {
              cur = m[1];
              if (!(cur in fields)) fields[cur] = '';
              if (!fieldLines[cur]) fieldLines[cur] = [];
              if (m[2]) {
                fields[cur] = (fields[cur] ? fields[cur] + ' ' : '') + m[2];
                fieldLines[cur].push(m[2].trim());
              }
            }
            else if (cur === '敌方单位') enemyLines.push(line);
            else if (cur) {
              fields[cur] = (fields[cur] ? fields[cur] + ' ' : '') + line;
              if (!fieldLines[cur]) fieldLines[cur] = [];
              fieldLines[cur].push(line);
            }
          });
          const enemies = enemyLines.map(csxParseEnemy);
          const allyRaw = fields['我方状态/资源'] || fields['我方状态'] || fields['我方资源'] || fields['我方'] || '';
          const allyLines = fieldLines['我方状态/资源'] || fieldLines['我方状态'] || fieldLines['我方资源'] || fieldLines['我方'] || [];
          const allies = csxParseAllies(allyRaw, allyLines);
          const acted = csxParseRoster(fields['本轮已行动'] || fields['已行动']);
          const unacted = csxParseRoster(fields['本轮未行动'] || fields['未行动']);
          const roundOver = !unacted.names.length;
          const roundText = fields['战斗轮次'] || fields['轮次'] || '';
          const axisText = fields['行动轴'] || '';
          let axisHtml = '';
          if (axisText) {
            const seq = axisText.split(/->|→|＞|>/).map(s => s.trim()).filter(Boolean);
            axisHtml = '<div class="cs-sec"><div class="cs-lbl"><i class="fa-solid fa-list-ol"></i>行动轴</div>'
              + '<div class="init-axis-seq">'
              + seq.map((s, i) => '<span class="init-seq-node">' + rpgEsc(s) + '</span>' + (i < seq.length - 1 ? '<i class="fa-solid fa-angle-right init-seq-arrow"></i>' : '')).join('')
              + '</div></div>';
          }
          const enemyHtml = enemies.map(e => {
            const rank = csxRankOf(e.tier) || (e.tier ? '杂兵' : '杂兵');
            const frame = '<div class="monster-icon-frame" data-rank="' + escapeHtmlAttr(rank) + '"></div>';
            const tagClasses = ['cs-tag cs-tag-gold', 'cs-tag cs-tag-red', 'cs-tag cs-tag-purple', 'cs-tag cs-tag-blue'];
            const tierParts = e.tier ? csxSplitTop(e.tier, '-').filter(Boolean) : [];
            const tags = [];
            tierParts.forEach((part, i) => {
              const toneClass = i === 0 ? 'cs-tag cs-tag-tier-main' : 'cs-tag cs-tag-tier-sub';
              tags.push('<span class="' + toneClass + '">' + rpgEsc(part) + '</span>');
            });
            e.statuses.forEach((s, i) => {
              tags.push('<span class="' + tagClasses[i % tagClasses.length] + '">' + rpgEsc(s) + '</span>');
            });
            let hp = '';
            if (e.hp && e.hp.max > 0) {
              const pct = Math.max(0, Math.min(100, Math.round(e.hp.cur / e.hp.max * 100)));
              hp = '<div class="flex items-center justify-between mb-1"><span class="cs-hplabel">HP</span><span class="cs-hptxt"><b>' + rpgEsc(e.hp.cur) + '</b> / ' + rpgEsc(e.hp.max) + '</span></div>'
                + '<div class="enemy-hp-bar mb-2"><div class="enemy-hp-fill" style="width:' + pct + '%"></div></div>';
            }
            return '<div class="cs-enemy">'
              + '<div class="flex items-start gap-3 mb-1 enemy-top-row">' + frame
              + '<div class="flex-1 min-w-0 enemy-name-block"><h3 class="cs-ename font-noto text-base font-bold">' + rpgEsc(e.name) + '</h3></div>'
              + (e.dist ? '<div class="flex-shrink-0 pt-1"><span class="cs-edist font-cinzel_body text-sm font-bold">' + rpgEsc(e.dist) + '</span></div>' : '')
              + '</div>'
              + (tags.length ? '<div class="flex items-center gap-2 mb-3 flex-wrap enemy-tag-row">' + tags.join(' ') + '</div>' : '')
              + hp
              + '</div>';
          }).join('');
          const allyHtml = allies.map(a => {
            const pal = csxPalette(a.name || 'User');
            const head = csxSplitSub(a.name || 'User');
            const chips = a.segs.map(s => csxChip(s, pal)).join('');
            const hpMatch = String(head.sub || '').match(/(\d+)\s*\/\s*(\d+)/);
            const hpMeta = hpMatch
              ? '<div class="cs-allyhpmeta"><span class="cs-allyhplabel">HP</span><span class="cs-allyhptxt"><b>' + rpgEsc(hpMatch[1]) + '</b> / ' + rpgEsc(hpMatch[2]) + '</span></div>'
              : '';
            const hpBar = hpMatch
              ? '<div class="cs-allyhpbar"><div class="enemy-hp-bar"><div class="enemy-hp-fill" style="width:' + Math.max(0, Math.min(100, Math.round((parseInt(hpMatch[1], 10) / Math.max(parseInt(hpMatch[2], 10), 1)) * 100))) + '%"></div></div></div>'
              : '';
            return '<div class="cs-ally"><div class="cs-allybox">'
              + '<div class="cs-allyhead"><span class="cs-aname">' + rpgEsc(head.main || 'User') + '</span>'
              + (!hpMatch && head.sub ? '<span class="cs-allystat">' + rpgEsc(head.sub) + '</span>' : '') + '</div>'
              + hpMeta + hpBar
              + '<div class="cs-chips">' + chips + '</div>'
              + '</div></div>';
          }).join('');
          const roster = r => r.names.length ? '<div class="cs-chips">' + r.names.map(n => '<span class="cs-pill">' + rpgEsc(n) + '</span>').join('') + '</div>' : '<span class="cs-empty">无</span>';
          const kv = [['队伍协作', fields['队伍协作'], 'fa-users'], ['距离变化', fields['距离变化'], 'fa-arrows-left-right']].filter(r => r[1])
            .map(r => '<div class="cs-kv"><span class="cs-k"><i class="fa-solid ' + r[2] + '"></i>' + r[0] + '</span><span class="cs-v">' + rpgEsc(r[1]) + '</span></div>').join('');
          return '<div class="log-card cs-card card-animate" style="animation-delay:' + (idx * 0.08) + 's">' +
            '<div class="cs-head"><span class="cs-hline"></span><i class="ra ra-crossed-swords cs-hic"></i><h3 class="cs-htitle">战斗快照</h3><i class="ra ra-crossed-swords cs-hic"></i><span class="cs-hline"></span>' +
            (roundText ? '<span class="cs-round cs-round-num"><i class="fa-solid fa-flag"></i> ' + rpgEsc(roundText) + '</span>' : (roundOver ? '<span class="cs-round"><i class="fa-solid fa-circle-check"></i> 轮次结束</span>' : '')) + '</div>' +
            '<div class="cs-body">' +
            axisHtml +
            (enemies.length ? '<div class="cs-sec"><div class="cs-lbl"><i class="fa-solid fa-skull"></i>敌方单位 <span class="cs-cnt">×' + enemies.length + '</span></div>' + enemyHtml + '</div>' : '') +
            (allies.length ? '<div class="cs-sec"><div class="cs-lbl"><i class="fa-solid fa-shield-halved"></i>我方状态 / 资源</div>' + allyHtml + '</div>' : '') +
            (kv ? '<div class="cs-sec">' + kv + '</div>' : '') +
            '<div class="cs-sec"><div class="cs-lbl"><i class="fa-solid fa-hourglass-end"></i>本轮行动</div><div class="cs-acts"><div class="cs-col"><div class="cs-ah cs-done">已行动</div>' + roster(acted) + (acted.note ? '<span class="cs-note">' + rpgEsc(acted.note) + '</span>' : '') + '</div><div class="cs-col"><div class="cs-ah cs-pend">未行动</div>' + roster(unacted) + (unacted.note ? '<span class="cs-note">' + rpgEsc(unacted.note) + '</span>' : '') + '</div></div></div>' +
            '</div></div>';
        }

        // ===== RPG LOG 总调度 =====
        function renderRpgCard(type, raw, idx) {
          const t = String(type || '').toLowerCase();
          const rendererMap = {
            dicecombat: renderRpgDiceCombat,
            dicecheck: renderRpgDiceCheck,
            initiative: renderRpgInitiative,
            enemyoverview: renderRpgEnemyOverview,
            summonoverview: renderRpgSummonOverview,
            lootlog: renderRpgLootLog,
            experiencelog: renderRpgExperienceLog,
            questcontract: renderRpgQuestContract,
            merchantstore: renderRpgMerchantStore,
            combatsnapshot: renderRpgCombatSnapshot
          };
          const renderer = rendererMap[t];
          return typeof renderer === 'function' ? renderer(raw, idx) : '';
        }

        function stripNowPlotTags(text) {
          return String(text || '').replace(/<\/?\s*now_plot\s*>/gi, '');
        }

    function processTextContent() {
      const contentDiv = document.getElementById('readingContent');
      if (!contentDiv) return;

      let initialHtml = stripNowPlotTags(contentDiv.innerHTML).trim();
      if (!initialHtml) return;

      // === 保护 markdown 代码块围栏 ```...``` ===
      // 代码块内的 <div>/<style> 等会被浏览器当作真实DOM解析并被后续HTML块提取逻辑抽走，
      // 破坏正文结构。此处先在字符串层面把代码块替换为纯文本占位符，最后再还原为转义后的 <pre><code>。
      const fencedCodeBlocks = [];
      initialHtml = initialHtml.replace(/```[\s\S]*?```/g, (block) => {
        const ph = 'RPCODEFENCE' + fencedCodeBlocks.length + 'FENCEEND';
        fencedCodeBlocks.push(block);
        return ph;
      });

      const workDiv = document.createElement('div');
      workDiv.innerHTML = initialHtml;
      contentDiv.setAttribute('aria-busy', 'true');
      try {

      // === Phase 1: DOM操作 - 提取HTML块(style+div / 顶层自定义HTML卡片)，保留原始DOM元素 ===
      const preservedBlocks = [];
      let preservedBlockIndex = 0;
      const standaloneHtmlBlockSelector = [
        ':scope > div[style]',
        ':scope > div[class]',
        ':scope > div[data-preserve-html]',
        ':scope > section[style]',
        ':scope > section[class]',
        ':scope > section[data-preserve-html]',
        ':scope > article[style]',
        ':scope > article[class]',
        ':scope > article[data-preserve-html]',
        ':scope > blockquote[style]',
        ':scope > blockquote[class]',
        ':scope > blockquote[data-preserve-html]',
        ':scope > figure[style]',
        ':scope > figure[class]',
        ':scope > figure[data-preserve-html]',
        ':scope > table[style]',
        ':scope > table[class]',
        ':scope > table[data-preserve-html]',
        ':scope > button',
        ':scope > a',
        ':scope > input',
        ':scope > textarea',
        ':scope > select'
      ].join(', ');
      const styleEls = Array.from(workDiv.querySelectorAll(':scope > style'));
      for (let si = 0; si < styleEls.length; si++) {
        const styleEl = styleEls[si];
        const scopeId = 'shb-' + Math.random().toString(36).substr(2, 6);
        styleEl.textContent = scopeCssSelectors(styleEl.textContent, scopeId);
        // 找到紧跟的div兄弟元素
        let nextEl = styleEl.nextSibling;
        while (nextEl && ((nextEl.nodeType === 3 && !nextEl.textContent.trim()) ||
          (nextEl.nodeType === 1 && nextEl.tagName === 'BR'))) {
          nextEl = nextEl.nextSibling;
        }
        const wrapper = document.createElement('div');
        wrapper.id = scopeId;
        wrapper.className = 'scoped-html-block';
        // 插入占位符文本
        const ph = '\n___HTMLBLOCK_' + (preservedBlockIndex++) + '___\n';
