      }

      // 顶层自定义HTML块默认保留，避免在 processParagraphs 中被当作普通正文剥离标签。
      Array.from(workDiv.querySelectorAll(standaloneHtmlBlockSelector)).forEach(blockEl => {
        if (blockEl.parentNode !== workDiv) return;
        neutralizeFloatingRoot(blockEl);
        const ph = '\n___HTMLBLOCK_' + (preservedBlockIndex++) + '___\n';
        workDiv.insertBefore(document.createTextNode(ph), blockEl);
        workDiv.removeChild(blockEl);
        preservedBlocks.push({ ph: ph.trim(), wrapper: blockEl });
      });

      // 保护第三方生图按钮，保留其原始节点及 addEventListener 监听器
      // 注意：workDiv 是 contentDiv.innerHTML 重新解析的克隆节点，监听器已丢失；
      // 必须用 contentDiv 里的【原始按钮】作为 wrapper，replaceChildren 移动节点时监听器才保留。
      // contentDiv 与 workDiv 同源，querySelectorAll 返回数量与文档序一致，按索引一一配对。
      const pluginButtonSelector = [
        'button.image-tag-button',
        'button.st-chatu8-image-button',
        'button[data-image-tag]',
        'button[data-link][data-request-id]'
      ].join(', ');
      const origButtons = Array.from(contentDiv.querySelectorAll(pluginButtonSelector));
      const cloneButtons = Array.from(workDiv.querySelectorAll(pluginButtonSelector));
      const n = Math.min(origButtons.length, cloneButtons.length);
      for (let bi = 0; bi < n; bi++) {
        const cloneBtn = cloneButtons[bi];
        const origBtn = origButtons[bi];
        if (!cloneBtn || !cloneBtn.parentNode) continue;
        const ph = '\n___HTMLBLOCK_' + (preservedBlockIndex++) + '___\n';
        cloneBtn.parentNode.insertBefore(document.createTextNode(ph), cloneBtn);
        cloneBtn.parentNode.removeChild(cloneBtn);
        preservedBlocks.push({ ph: ph.trim(), wrapper: origBtn });
      }

      // 保护图片占位 span（生图回填目标），保留原始节点及 data-request-id
      // 生图完成后回调按 span[data-request-id] 查找回填目标；若 span 被 replaceChildren
      // 克隆替换、且因 <image>-><img> 解析错位，回填会失败。同样按索引保护原始 span。
      const pluginSpanSelector = '.st-chatu8-image-span, span[data-request-id]';
      const origSpans = Array.from(contentDiv.querySelectorAll(pluginSpanSelector));
      const cloneSpans = Array.from(workDiv.querySelectorAll(pluginSpanSelector));
      const ns = Math.min(origSpans.length, cloneSpans.length);
      for (let si = 0; si < ns; si++) {
        const cloneSpan = cloneSpans[si];
        const origSpan = origSpans[si];
        if (!cloneSpan || !cloneSpan.parentNode) continue;
        const ph = '\n___HTMLBLOCK_' + (preservedBlockIndex++) + '___\n';
        cloneSpan.parentNode.insertBefore(document.createTextNode(ph), cloneSpan);
        cloneSpan.parentNode.removeChild(cloneSpan);
        preservedBlocks.push({ ph: ph.trim(), wrapper: origSpan });
      }

      // === Phase 2: 读取innerHTML（HTML块已被替换为文本占位符）===
      let rawText = workDiv.innerHTML.trim();
      if (!rawText) return;

      // 解码HTML实体，使转义标签（如 &lt;img&gt;）可被后续逻辑识别
      rawText = decodeHtmlEntities(rawText);

      // 标签匹配：图片标签 + 创始回廊 RPG 日志标签。
      const tagPatterns = [
        { regex: /<Image>([\s\S]*?)<\/Image>/gi, type: 'image-tag' },
        { regex: /<pic>([\s\S]*?)<\/pic>/gi, type: 'image-tag' },
        { regex: /<img\b[^>]*>/gi, type: 'html-img' },
        { regex: /<(DiceCombat)>([\s\S]*?)<\/DiceCombat>/gi, type: 'rpg-log' },
        { regex: /<(DiceCheck)>([\s\S]*?)<\/DiceCheck>/gi, type: 'rpg-log' },
        { regex: /<(Initiative)>([\s\S]*?)<\/Initiative>/gi, type: 'rpg-log' },
        { regex: /<(EnemyOverview)>([\s\S]*?)<\/EnemyOverview>/gi, type: 'rpg-log' },
        { regex: /<(SummonOverview)>([\s\S]*?)<\/SummonOverview>/gi, type: 'rpg-log' },
        { regex: /<(LootLog)>([\s\S]*?)<\/LootLog>/gi, type: 'rpg-log' },
        { regex: /<(ExperienceLog)>([\s\S]*?)<\/ExperienceLog>/gi, type: 'rpg-log' },
        { regex: /<(QuestContract)>([\s\S]*?)<\/QuestContract>/gi, type: 'rpg-log' },
        { regex: /<(MerchantStore)>([\s\S]*?)<\/MerchantStore>/gi, type: 'rpg-log' },
        { regex: /<(CombatSnapshot)>([\s\S]*?)<\/CombatSnapshot>/gi, type: 'rpg-log' }
      ];
      const matches = [];
      if (rawText.includes('<')) {
        tagPatterns.forEach(config => {
          let match;
          config.regex.lastIndex = 0;
          while ((match = config.regex.exec(rawText)) !== null) {
            if (config.type === 'image-tag') {
              matches.push({ index: match.index, length: match[0].length, content: match[1].trim(), raw: match[0], type: 'image-tag' });
            } else if (config.type === 'html-img') {
              matches.push({ index: match.index, length: match[0].length, content: match[0], raw: match[0], type: 'html-img' });
            } else {
              matches.push({ index: match.index, length: match[0].length, rpgType: match[1], content: match[2], raw: match[0], type: 'rpg-log', rpgIdx: matches.length });
            }
          }
        });
      }

      matches.sort((a, b) => a.index - b.index);
      // 去重：移除被更大匹配包含的重叠项
      for (let i = matches.length - 1; i > 0; i--) {
        const prev = matches[i - 1];
        if (matches[i].index < prev.index + prev.length) {
          if (matches[i].length > prev.length) matches.splice(i - 1, 1);
          else matches.splice(i, 1);
        }
      }

      // === Phase 2: 文本处理 - 只处理受支持标签，占位符原样保留 ===
      const htmlParts = [];
      let lastIndex = 0;
      // 单张卡片渲染失败不能连坐：AI 写歪一个字段、或某个渲染函数自己抛了，
      // 以前会顺着 forEach 冒到 processTextContent 外面，整篇正文都不写回 DOM，
      // 页面直接白掉。现在每张卡片各自 try，出事只打日志，那一段退回纯文本排版。
      const renderTag = (match) => {
        try {
          if (match.type === 'image-tag') return renderImageTag(match);
          if (match.type === 'html-img') return createInteractiveImageContainer(match.content);
          if (match.type === 'rpg-log') return '<div class="rpg-log-section">' + renderRpgCard(match.rpgType, match.content, match.rpgIdx) + '</div>';
        } catch (err) {
          console.error('[正文美化] 卡片渲染失败，已退回纯文本：' + match.type, err);
        }
        return processParagraphs(match.raw || match.content || '');
      };
      matches.forEach(match => {
        const beforeText = rawText.substring(lastIndex, match.index);
        if (beforeText.trim()) htmlParts.push(processParagraphs(beforeText));
        htmlParts.push(renderTag(match));
        lastIndex = match.index + match.length;
      });
      const remainingText = rawText.substring(lastIndex);
      if (remainingText.trim()) htmlParts.push(processParagraphs(remainingText));
      workDiv.innerHTML = htmlParts.join('');

      // === Phase 3: 恢复保存的HTML块 - 将占位符替换为原始DOM元素 ===
      if (preservedBlocks.length > 0) {
        const walker = document.createTreeWalker(workDiv, NodeFilter.SHOW_TEXT, null, false);
        const textNodes = [];
        let node;
        while ((node = walker.nextNode())) textNodes.push(node);
        for (const block of preservedBlocks) {
          for (const tn of textNodes) {
            if (tn.textContent.includes(block.ph)) {
              const parent = tn.parentNode;
              const trimmedContent = tn.textContent.replace(block.ph, '').trim();
              // 如果占位符独占一个<p>标签（内容只有占位符），替换整个<p>
              if (parent.tagName === 'P' && !trimmedContent) {
                parent.parentNode.insertBefore(block.wrapper, parent);
                parent.parentNode.removeChild(parent);
              } else {
                // 其他情况：在文本节点位置插入保存的DOM元素
                const parts = tn.textContent.split(block.ph);
                if (parts[0]) parent.insertBefore(document.createTextNode(parts[0]), tn);
                parent.insertBefore(block.wrapper, tn);
                if (parts[1]) parent.insertBefore(document.createTextNode(parts[1]), tn);
                parent.removeChild(tn);
              }
              break;
            }
          }
        }
      }

      // === 还原被保护的代码块占位符为转义后的 <pre><code> ===
      if (fencedCodeBlocks.length > 0) {
        const walker = document.createTreeWalker(workDiv, NodeFilter.SHOW_TEXT, null, false);
        const textNodes = [];
        let node;
        while ((node = walker.nextNode())) textNodes.push(node);
        fencedCodeBlocks.forEach((block, i) => {
          const ph = 'RPCODEFENCE' + i + 'FENCEEND';
          // 去掉首尾围栏及首行语言标注，内部内容整体转义
          const inner = block
            .replace(/^```[^\n]*\r?\n?/, '')
            .replace(/\r?\n?```\s*$/, '');
          const pre = document.createElement('pre');
          pre.className = 'rp-code-block';
          const code = document.createElement('code');
          code.textContent = inner;
          pre.appendChild(code);
          for (const tn of textNodes) {
            if (!tn.parentNode || !tn.textContent.includes(ph)) continue;
            const parent = tn.parentNode;
            const rest = tn.textContent.replace(ph, '').trim();
            if (parent.tagName === 'P' && !rest) {
              parent.parentNode.insertBefore(pre, parent);
              parent.parentNode.removeChild(parent);
            } else {
              const parts = tn.textContent.split(ph);
              if (parts[0]) parent.insertBefore(document.createTextNode(parts[0]), tn);
              parent.insertBefore(pre, tn);
              if (parts[1]) parent.insertBefore(document.createTextNode(parts[1]), tn);
              parent.removeChild(tn);
            }
            break;
          }
        });
      }

      // 为敌人卡片注入SVG图标
      workDiv.querySelectorAll('.monster-icon-frame[data-rank]').forEach(frame => {
        const svg = getRankSvg(frame.dataset.rank);
        if (svg) frame.innerHTML = svg;
      });

      // 过滤全文中的 ** 符号
      removeAsterisks(workDiv);
      contentDiv.replaceChildren(...Array.from(workDiv.childNodes));

      // === [修复] 智绘姬按钮事件丢失 ===
      // replaceChildren重建DOM后按钮会丢失click事件(变成无事件克隆节点)。
      // 用replaceChildren之前保存的原始按钮(带事件)替换克隆按钮(无事件)，确保手动点击能触发生图。
      ;(function(){
        var chatu8Sel = 'button.image-tag-button, button.st-chatu8-image-button, button[data-image-tag], button[data-link][data-request-id]';
        var cloneByLink = new Map();
        Array.from(contentDiv.querySelectorAll(chatu8Sel)).forEach(function(button) {
          var link = button.dataset.link || button.getAttribute('data-image-tag') || '';
          if (link && !cloneByLink.has(link)) cloneByLink.set(link, button);
        });
        origButtons.forEach(function(ob){
          if (ob.hasAttribute('data-loading') || contentDiv.contains(ob)) return;
          var link = ob.dataset.link || ob.getAttribute('data-image-tag') || '';
          if (!link) return;
          var clone = cloneByLink.get(link);
          if (clone && clone !== ob && clone.parentNode) clone.parentNode.replaceChild(ob, clone);
          else contentDiv.appendChild(ob);
        });
      })();
      } finally {
        contentDiv.removeAttribute('aria-busy');
      }
    }

    // 递归遍历文本节点，移除 ** 符号（跳过代码块，避免破坏代码内容）
    function removeAsterisks(node) {
      if (node.nodeType === Node.TEXT_NODE) {
        node.textContent = node.textContent.replace(/\*\*/g, '');
      } else {
        if (node.nodeType === Node.ELEMENT_NODE && (node.tagName === 'PRE' || node.tagName === 'CODE')) return;
        node.childNodes.forEach(removeAsterisks);
      }
    }

    // 清理文本中的HTML注释
    function cleanHtmlComments(text) {
      return text.replace(new RegExp('<' + '!--[\\s\\S]*?--' + '>', 'g'), '');
    }

    // 解码常见HTML实体，支持一层嵌套编码（如 &amp;lt;img&amp;gt;）
    let htmlEntityDecoder = null;

    function decodeHtmlEntities(text) {
      if (!text || text.indexOf('&') === -1) return text;
      const ta = htmlEntityDecoder || (htmlEntityDecoder = document.createElement('textarea'));
      let decoded = text;
      for (let i = 0; i < 5; i++) {
        const prev = decoded;
        ta.innerHTML = decoded;
        decoded = ta.value;
        if (decoded === prev) break;
        if (decoded.indexOf('&') === -1) break;
      }
      return decoded;
    }

    // 对CSS选择器添加作用域前缀，防止样式泄露到外部
    function scopeCssSelectors(css, scopeId) {
      const prefix = '#' + scopeId;
      // 匹配 selector { body } 格式的CSS规则
      return css.replace(/([^{}]+)\{([^{}]*)\}/g, function (match, selector, body) {
        var scoped = selector.split(',').map(function (s) {
          s = s.trim();
          // 跳过@规则、关键帧步骤
          if (!s || s.charAt(0) === '@' || s === 'from' || s === 'to' || /^\d+%$/.test(s)) return s;
          return prefix + ' ' + s;
        }).join(', ');
        // 不保留悬浮：把 <style> 里定义的 fixed/sticky 定位改为 static，让块顺着正文排版
        body = body.replace(/position\s*:\s*(fixed|sticky)\b\s*(!important)?/gi, 'position: static');
        return scoped + '{' + body + '}';
      });
    }

    // 中和保留块根元素上的【内联】悬浮定位，使其回到文档流、正常占位排版。
    // 只处理根元素自身，不动其后代（保留卡片内部 absolute 装饰等布局）。
    function neutralizeFloatingRoot(el) {
      if (!el || el.nodeType !== 1 || !el.style) return;
      const pos = (el.style.position || '').toLowerCase();
      if (pos === 'fixed' || pos === 'sticky' || pos === 'absolute') {
        el.style.setProperty('position', 'static', 'important');
        // 清除随定位失效的偏移，避免元素被 transform/inset 拉出正文区
        ['top', 'right', 'bottom', 'left', 'inset', 'z-index'].forEach(p => el.style.removeProperty(p));
      }
    }

    function processParagraphs(text) {
      // 清理HTML注释
      text = cleanHtmlComments(text);
      // 剥离残留的HTML标签（style块整体移除，其他标签只去标签保留文本）
      text = text.replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '');
      text = text.replace(/<\/?(?:div|p|ul|ol|li|h[1-6]|table|tr|td|th|thead|tbody|br|hr|blockquote|pre|code|section|article|header|footer|nav|main|aside|figure|figcaption)[^>]*>/gi, '\n');
      text = text.replace(/<\/?(?:span|strong|em|b|i|a)[^>]*>/gi, '');
      let cleanText = text.replace(/<\/?Image(?!\s)>/gi, '');

      // 清理每行中重复的角色名标记：保留行首的 {角色名}，移除后续的 {角色名}
      // 例如 "{艾玛}{艾玛}「对话」" 变成 "{艾玛}「对话」"
      cleanText = cleanText.split('\n').map(line => {
        // 匹配行首的角色标记
        const firstTagMatch = line.match(/^(\s*\{[^}]+\})/);
        if (firstTagMatch) {
          const firstTag = firstTagMatch[1];
          const rest = line.substring(firstTag.length);
          // 移除剩余部分中的所有角色名标记
          const cleanRest = rest.replace(/\{[^}]+\}/g, '');
          return firstTag + cleanRest;
        }
        return line;
      }).join('\n');

      const lines = cleanText.split(/\n+/).filter(p => p.trim().length > 0);

      let resultHtml = '';
      let pendingDialogue = null;

      const flushPending = () => {
        if (pendingDialogue) {
          const mergedText = pendingDialogue.texts.map(t => processDialogueContent(t)).join('<br><br>');
          resultHtml += createDialogueElement(pendingDialogue.name, mergedText, true);
          pendingDialogue = null;
        }
      };

      // 辅助函数：检查是否可以合并
      const checkCanMerge = (normalizedName) => {
        if (!pendingDialogue) return false;
        if (pendingDialogue.normalizedName === normalizedName) return true;
        const c1 = CHARACTER_CONFIG[pendingDialogue.normalizedName];
        const c2 = CHARACTER_CONFIG[normalizedName];
        if (c1 && c2 && c1.avatar && c2.avatar && c1.avatar === c2.avatar) return true;
        return false;
      };

      for (let line of lines) {
        line = line.trim();

        // 跳过双花括号格式 {{...}}，这是情绪/动作描述，不作为对话处理
        if (/^\{\{.*\}\}/.test(line)) {
          flushPending();
          resultHtml += `<p>${escapeHtmlText(line)}</p>`;
          continue;
        }

        let rawName = null;
        let content = null;
        let normalizedName = null;

        // 1. 尝试花括号格式: {角色名}「对话」
        const braceNamePattern = /^[\s]*\{([^}]+)\}[\s]*(.+)$/;
        const braceMatch = line.match(braceNamePattern);

        if (braceMatch) {
          rawName = braceMatch[1].trim();
          content = braceMatch[2].trim();
          normalizedName = normalizeDisplayName(rawName);

          // 检查是否是有头像的已知角色
          const config = CHARACTER_CONFIG[normalizedName];
          if (!config || !config.avatar) {
            // 不是已知角色，过滤掉花括号标记，按普通正文处理，保留引号高亮/图片解析等能力
            flushPending();
            resultHtml += processLineWithImages(content);
            continue;
          }
        }
        // 只处理明确的 {角色名} 格式

        if (rawName && content && normalizedName) {
          // 是对话行
          if (checkCanMerge(normalizedName)) {
            pendingDialogue.texts.push(content);
          } else {
            flushPending();
            pendingDialogue = {
              name: rawName,
              normalizedName: normalizedName,
              texts: [content]
            };
          }
        } else {
          // 非对话行，或无法识别的格式
          flushPending();
          resultHtml += processLineWithImages(line);
        }
      }
      flushPending();
      return resultHtml;
    }

    function createNamedInnerVoiceElement(rawName, thought) {
      const name = String(rawName || '').trim() || '心声';
      const text = String(thought || '').trim();
      const safeName = escapeHtmlText(name);
      const safeText = escapeHtmlText(text);
      const open = window.__namedInnerVoiceDefaultExpand === true;
      const expanded = open ? 'true' : 'false';
      return '<div class="named-inner-voice' + (open ? ' is-open' : '') + '" data-inner-voice="true">' +
        '<button class="named-inner-voice__trigger" type="button" data-inner-voice-toggle aria-expanded="' + expanded + '" aria-label="展开或收起' + safeName + '的心声">' +
        '<span class="named-inner-voice__label">' + safeName + ' · 心声</span>' +
        '<span class="named-inner-voice__dots" aria-hidden="true"><i></i><i></i><i></i></span></button>' +
        '<div class="named-inner-voice__body" aria-hidden="' + (open ? 'false' : 'true') + '"><div class="named-inner-voice__body-inner">' +
        '<div class="named-inner-voice__text">' + safeText + '</div></div></div></div>';
    }

    function processLineWithImages(line) {
      const sourceLine = String(line || '');
      const htmlLine = sourceLine.indexOf('&') === -1 ? sourceLine : decodeHtmlEntities(sourceLine);
      let decodedLine = htmlLine;
      if (/<\/?[a-z][^>]*>/i.test(htmlLine)) {
        const tempDiv = document.createElement('div');
        tempDiv.innerHTML = htmlLine;
        decodedLine = tempDiv.textContent || tempDiv.innerText || htmlLine;
      }

      // 跳过双花括号格式 {{...}}
      if (/^\{\{.*\}\}/.test(decodedLine.trim())) {
        return `<p>${escapeHtmlText(decodedLine)}</p>`;
      }

      // (角色名：*心理活动想法*)：角色名进入标记，心理活动使用比正文略小的心声字级。
      const namedInnerVoiceMatch = decodedLine.trim().match(/^[\(（]\s*([^():：\n]+?)\s*[:：]\s*\*([^*\n]+?)\*\s*[\)）]$/);
      if (namedInnerVoiceMatch) {
        return createNamedInnerVoiceElement(namedInnerVoiceMatch[1], namedInnerVoiceMatch[2]);
      }

      // 整行 *...* 作为心里话处理；行内 *...* 仍由 highlightInlineDialogueQuotes 转为 narration-em。
      const innerVoiceMatch = decodedLine.trim().match(/^\*([^*\n]+?)\*$/);
      if (innerVoiceMatch) {
        return `<div class="inner-voice"><p>${escapeHtmlText(innerVoiceMatch[1].trim())}</p></div>`;
      }
      const braceNamePattern = /^[\s]*\{([^}]+)\}[\s]*(.+)$/;
      const braceMatch = decodedLine.match(braceNamePattern);

      if (braceMatch) {
        const rawName = braceMatch[1].trim();
        const normalizedName = normalizeDisplayName(rawName);
        // 校验是否是有头像的已知角色
        const config = CHARACTER_CONFIG[normalizedName];
        if (config && config.avatar) {
          return createDialogueElement(rawName, braceMatch[2].trim());
        }
        // 不是已知角色，过滤掉花括号标记，内容作为普通文本显示
        return `<p>${highlightInlineDialogueQuotes(braceMatch[2].trim())}</p>`;
      }

      // 只处理明确的 {角色名} 格式

      // 图片处理 - 检测原始line中的<img>标签（decodedLine已被去除所有HTML标签，无法检测）
      const imgRegex = /<img[^>]*>/i;
      if (imgRegex.test(htmlLine)) {
        const div = document.createElement('div');
        div.innerHTML = htmlLine;
        return createInteractiveImageContainer(div.innerHTML);
      } else {
        return `<p>${highlightInlineDialogueQuotes(decodedLine)}</p>`;
      }
    }

    const IMAGE_GEN_RESPONSE_EVENT = 'generate-image-response';
    const IMAGE_GEN_AUTO_RERENDER = false;
    let imageGenRerenderTimer = null;

    function hasUnprocessedImageTag(html) {
      if (!html) return false;
      return /<\s*Image\b|<\s*pic\b/i.test(html) || /&lt;\s*(Image|pic)\b/i.test(html);
    }

    function scheduleImageGenRerender() {
      if (imageGenRerenderTimer) clearTimeout(imageGenRerenderTimer);
      imageGenRerenderTimer = setTimeout(() => {
        imageGenRerenderTimer = null;
        try {
          const contentDiv = document.getElementById('readingContent');
          if (!contentDiv) return;
          if (contentDiv.getAttribute('aria-busy') === 'true') return;
          const currentHtml = contentDiv.innerHTML || '';
          if (!hasUnprocessedImageTag(currentHtml)) return;
          processTextContent();
          if (typeof applyImageSize === 'function') applyImageSize();
        } catch (e) {
          console.warn('[正文美化] 生图响应重渲染失败:', e);
        }
      }, 30);
    }

    function initImageGenResponseListener() {
      if (window.__imageGenResponseBound) return;
      let eventOnFn;
      try {
        const win = window.parent || window;
        eventOnFn = win.eventOn || window.eventOn;
      } catch (e) {
        eventOnFn = window.eventOn;
      }
      if (typeof eventOnFn !== 'function') return;
      window.__imageGenResponseBound = true;
      eventOnFn(IMAGE_GEN_RESPONSE_EVENT, function (responseData) {
        if (!IMAGE_GEN_AUTO_RERENDER) return;
        if (responseData && responseData.success === false) return;
        scheduleImageGenRerender();
      });
    }

    function isImageUrlLike(text) {
      const trimmed = String(text || '').trim();
      if (!trimmed) return false;
      if (/^(SFW|NSFW)\//.test(trimmed)) return true;
      if (/^data:image\//i.test(trimmed)) return true;
      if (/^https?:\/\//i.test(trimmed)) return true;
      if (/^(?:\/|\.\/|\.\.\/)/.test(trimmed)) return true;
      if (/\.(webp|png|jpg|jpeg|gif|bmp|svg)(\?|#|$)/i.test(trimmed)) return true;
      return false;
    }

    function renderImageTag(match) {
      const content = match && typeof match.content === 'string' ? match.content : '';
      if (isImageUrlLike(content)) {
        return createImageElement(content);
      }
      return match && match.raw ? match.raw : '';
    }

    function createImageElement(imageUrl) {
      let trimmedUrl = imageUrl.trim();
      if (!trimmedUrl) return '';

      // 处理 <pic> 标签的相对路径格式，如 "SFW/希罗/通常1"
      // 补全为完整URL
      if (/^(SFW|NSFW)\//.test(trimmedUrl)) {
        // 如果没有.webp后缀，添加它
        if (!trimmedUrl.endsWith('.webp')) {
          trimmedUrl = trimmedUrl + '.webp';
        }
        trimmedUrl = 'https://dnf.rown.dpdns.org/' + trimmedUrl;
      }

      const imgTag = `<img src="${escapeHtmlAttr(trimmedUrl)}" alt="图片" loading="lazy" decoding="async">`;
      return createInteractiveImageContainer(imgTag);
    }

    // 辅助函数：为缺少编号的图片URL自动添加随机编号
    function autoAssignImageNumber(imgSrc) {
      try {
        const parts = String(imgSrc || '').split('/');
        const ci = parts.findIndex(part => part === 'NSFW' || part === 'SFW');
        if (ci < 0 || ci + 2 >= parts.length) return imgSrc;
        const character = safeDecodeURIComponent(parts[ci + 1]);
        const fileName = safeDecodeURIComponent(parts[ci + 2]).replace(/\.webp(?:[?#].*)?$/i, '');
        if (/^(.+?)(\d+)$/.test(fileName)) return imgSrc;
        const entry = findImageListEntry(parts[ci], character, fileName);
        if (!entry || !entry.maxNumber) return imgSrc;
        const next = entry.numbers[Math.floor(Math.random() * entry.numbers.length)];
        parts[ci + 2] = encodeURIComponent(fileName + next + '.webp');
        return parts.join('/');
      } catch (e) {
        console.error('Image number assignment failed:', e);
        return imgSrc;
      }
    }

    function createInteractiveImageContainer(imgContent, forceExpand) {
      const uniqueId = 'img-' + Math.random().toString(36).substr(2, 9);
      const autoExpand = !!forceExpand || localStorage.getItem('image-auto-expand') !== 'false';
      const expandedClass = autoExpand ? ' expanded' : '';
      const buttonClass = autoExpand ? ' expanded' : '';
      const buttonText = autoExpand ? '\u6536\u8d77\u63d2\u753b' : '\u67e5\u770b\u63d2\u753b';
      let isCgImage = false;
      const srcMatch = imgContent.match(/src=["']([^"']+)["']/i);
      if (srcMatch) {
        const originalSrc = srcMatch[1];
        const newSrc = autoAssignImageNumber(originalSrc);
        if (newSrc !== originalSrc) imgContent = imgContent.replace(originalSrc, newSrc);
        isCgImage = /(^|\/)(NSFW|SFW)\//i.test(newSrc);
        if (isCgImage) imgContent = imgContent.replace(/<img\s/i, '<img onload="recordCGUnlock(this.currentSrc || this.src)" ');
      }
      const refreshButton = isCgImage
        ? `<button class="image-refresh-btn" onclick="refreshImage('${uniqueId}', event)" title="Refresh image" aria-label="Refresh image">&#8635;</button>`
        : '';
      return `<div class="image-container">
        <div style="display:flex;justify-content:center;align-items:center;gap:8px;">
          <button class="image-toggle-btn${buttonClass}" onclick="toggleImage('${uniqueId}')">
            <span class="image-toggle-text">${buttonText}</span>
          </button>
          ${refreshButton}
        </div>
        <div class="image-content${expandedClass}" id="${uniqueId}" style="text-align:center;">
          ${imgContent}
        </div>
      </div>`;
    }
    window.toggleImage = function (imageId) {
      const imageContent = document.getElementById(imageId);
      const button = imageContent.previousElementSibling.querySelector('.image-toggle-btn');
      const textSpan = button.querySelector('.image-toggle-text');
      if (imageContent.classList.contains('expanded')) {
        imageContent.classList.remove('expanded');
        button.classList.remove('expanded');
        textSpan.textContent = '查看插画';
      } else {
        imageContent.classList.add('expanded');
        button.classList.add('expanded');
        textSpan.textContent = '收起插画';
      }
    };

    let readingFontSize = 18;
    let imageSize = 70; // 默认70%
    let readingWidthLevel = 0;
    const READING_WIDTH_STORAGE_KEY = 'reading-width-level-v2';
    const READING_WIDTH_LEVELS = [
      { label: '最窄', chatWidth: 50 },
      { label: '稍宽', chatWidth: 60 },
      { label: '较宽', chatWidth: 70 },
      { label: '宽', chatWidth: 80 },
      { label: '最宽', chatWidth: 90 }
    ];
    const READING_FONT_PRESETS = {
      'theme-default': {
        label: '跟随主题',
        family: ''
      },
      'zhenkai': {
        label: '霞鹜臻楷',
        family: '"LXGW ZhenKai GB", "LXGW ZhenKai", "Source Han Serif SC", "Songti SC", "STSong", "SimSun", serif'
      },
      'noto-serif': {
        label: '思源宋体',
        family: '"Source Han Serif SC", "Source Han Serif CN", "Noto Serif CJK SC", "Noto Serif SC", "Songti SC", "STSong", serif'
      },
      'yahei': {
        label: '微软雅黑',
        family: '"Microsoft YaHei UI", "Microsoft YaHei", "PingFang SC", "Noto Sans SC", sans-serif'
      },
      'heiti': {
        label: '黑体',
        family: '"SimHei", "Heiti SC", "Microsoft YaHei UI", sans-serif'
      },
      'songti': {
        label: '宋体',
        family: '"SimSun", "Songti SC", "STSong", "Noto Serif SC", serif'
      },
      'kaiti': {
